export const defaultLessonTexts: Record<string, string> = {
  "warsh-unit-0-u0-l1": "## ما علم القراءات؟\n\n### \n 1 \n تعريف القراءة\n\n القراءة هي: المذهب الذي ذهب إليه إمام من أئمة القراء في كيفية النطق بالقرآن الكريم، والذي ينسب إليه لكونه قد لزمه وأقرأ به، مع اتفاق هذا المذهب مع خط المصحف العثماني وتلقيه بالسند المتصل إلى رسول الله ﷺ.\n\n### \n 2 \n تعريف الرواية\n\n الرواية هي: ما نُسب للراوي عن الإمام. والراوي هو من أخذ القراءة عن الإمام مباشرة أو بواسطة. فكل ما يُنسب إلى ورش عن نافع يُسمى \"رواية\".\n\n### \n 3 \n تعريف الطريق\n\n الطريق هو: ما نُسب للآخذ عن الراوي وإن سفل. فمثلاً طريق \"الأزرق\" عن ورش، وطريق \"الشاطبية\" (التي اختارت طريق الأزرق) عن ورش.\n\n### خلاصة المعنى\n\n* \n • \n **القراءة:** نافع (الإمام) \n\n* \n • \n **الرواية:** ورش (عن نافع) \n\n* \n • \n **الطريق:** الشاطبية (بواسطة الأزرق عن ورش)",
  "u0-l1": "## ما علم القراءات؟\n\n### \n 1 \n تعريف القراءة\n\n القراءة هي: المذهب الذي ذهب إليه إمام من أئمة القراء في كيفية النطق بالقرآن الكريم، والذي ينسب إليه لكونه قد لزمه وأقرأ به، مع اتفاق هذا المذهب مع خط المصحف العثماني وتلقيه بالسند المتصل إلى رسول الله ﷺ.\n\n### \n 2 \n تعريف الرواية\n\n الرواية هي: ما نُسب للراوي عن الإمام. والراوي هو من أخذ القراءة عن الإمام مباشرة أو بواسطة. فكل ما يُنسب إلى ورش عن نافع يُسمى \"رواية\".\n\n### \n 3 \n تعريف الطريق\n\n الطريق هو: ما نُسب للآخذ عن الراوي وإن سفل. فمثلاً طريق \"الأزرق\" عن ورش، وطريق \"الشاطبية\" (التي اختارت طريق الأزرق) عن ورش.\n\n### خلاصة المعنى\n\n* \n • \n **القراءة:** نافع (الإمام) \n\n* \n • \n **الرواية:** ورش (عن نافع) \n\n* \n • \n **الطريق:** الشاطبية (بواسطة الأزرق عن ورش)",
  "warsh-unit-0-u0-l2": "## ترجمة الإمام نافع\n\n### اسمه ونسبه\n\nنافع بن عبد الرحمن بن أبي نعيم، الليثي بالولاء، المدني.\n\n### كنيته\n\nأبو رُوَيم، وقيل: أبو الحسن، وقيل: أبو عبد الرحمن.\n\n### مولده ووفاته\n\nولد في حدود سنة (70هـ)، وتوفي بالمدينة المنورة سنة (169هـ) وقيل غير ذلك.\n\n### مكانته العلمية\n\nإمام دار الهجرة في القراءة. انتهت إليه رياسة الإقراء بالمدينة، وأجمع الناس على قراءته.\n\n### شيوخه في القراءة\n\n أخذ القراءة عرضاً عن سبعين من التابعين، من أبرزهم:\n\n* أبو جعفر يزيد بن القعقاع\n \n* شيبة بن نصاح\n \n* عبد الرحمن بن هرمز الأعرج\n \n* مسلم بن جندب\n \n* يزيد بن رومان\n\n### أشهر من قرأ عليه (الرواة)\n\n قرأ عليه خلائق لا يحصون، واشتهر من الرواة عنه راويان أساسيان في منظومة القراءات السبع:\n\n 1. قالون (عيسى بن مينا) \n 2. ورش (عثمان بن سعيد)",
  "u0-l2": "## ترجمة الإمام نافع\n\n### اسمه ونسبه\n\nنافع بن عبد الرحمن بن أبي نعيم، الليثي بالولاء، المدني.\n\n### كنيته\n\nأبو رُوَيم، وقيل: أبو الحسن، وقيل: أبو عبد الرحمن.\n\n### مولده ووفاته\n\nولد في حدود سنة (70هـ)، وتوفي بالمدينة المنورة سنة (169هـ) وقيل غير ذلك.\n\n### مكانته العلمية\n\nإمام دار الهجرة في القراءة. انتهت إليه رياسة الإقراء بالمدينة، وأجمع الناس على قراءته.\n\n### شيوخه في القراءة\n\n أخذ القراءة عرضاً عن سبعين من التابعين، من أبرزهم:\n\n* أبو جعفر يزيد بن القعقاع\n \n* شيبة بن نصاح\n \n* عبد الرحمن بن هرمز الأعرج\n \n* مسلم بن جندب\n \n* يزيد بن رومان\n\n### أشهر من قرأ عليه (الرواة)\n\n قرأ عليه خلائق لا يحصون، واشتهر من الرواة عنه راويان أساسيان في منظومة القراءات السبع:\n\n 1. قالون (عيسى بن مينا) \n 2. ورش (عثمان بن سعيد)",
  "warsh-unit-0-u0-l3": "## إسناد قراءة الإمام نافع\n\nإسناد قراءة الإمام نافع من أعلى الأسانيد وأوثقها، متصل بالنبي ﷺ عبر الصحابة والتابعين في المدينة المنورة.\n\n### النبي محمد ﷺ\n\n### كبار الصحابة\n\nأبي بن كعب، زيد بن ثابت، عمر بن الخطاب، عبد الله بن عباس (رضي الله عنهم)\n\n### أئمة التابعين بالمدينة\n\nأبو هريرة (قرأ على أبي بن كعب)، ابن عباس (قرأ على زيد وأبي)\n\nعبد الرحمن بن هرمز الأعرج، أبو جعفر يزيد بن القعقاع، شيبة بن نصاح\n\n### الإمام نافع المدني\n\nأخذ عن سبعين من التابعين\n\n#### قالون\n\n#### ورش",
  "u0-l3": "## إسناد قراءة الإمام نافع\n\nإسناد قراءة الإمام نافع من أعلى الأسانيد وأوثقها، متصل بالنبي ﷺ عبر الصحابة والتابعين في المدينة المنورة.\n\n### النبي محمد ﷺ\n\n### كبار الصحابة\n\nأبي بن كعب، زيد بن ثابت، عمر بن الخطاب، عبد الله بن عباس (رضي الله عنهم)\n\n### أئمة التابعين بالمدينة\n\nأبو هريرة (قرأ على أبي بن كعب)، ابن عباس (قرأ على زيد وأبي)\n\nعبد الرحمن بن هرمز الأعرج، أبو جعفر يزيد بن القعقاع، شيبة بن نصاح\n\n### الإمام نافع المدني\n\nأخذ عن سبعين من التابعين\n\n#### قالون\n\n#### ورش",
  "warsh-unit-0-u0-l4": "## ترجمة الإمام ورش\n\n### البطاقة الشخصية\n\n* **الاسم:** عثمان بن سعيد بن عبد الله، المصري، وقيل: القبطي، وقيل: مولى آل الزبير.\n \n* **الكنية:** أبو سعيد.\n \n* **اللقب:** ورش (وهو اللقب الذي اشتهر به).\n \n* **المولد:** وُلد في مصر سنة (110 هـ).\n \n* **الوفاة:** توفي بمصر سنة (197 هـ).\n\n### سبب تسميته بـ \"ورش\"\n\n ذكر العلماء أن الإمام نافعًا هو من لقبه بـ \"ورش\" لشدة بياضه (والورش شيء يصنع من اللبن). وقيل: لقصره وخفة حركته تشبيهاً بطائر يسمى الورشان. وكان الإمام ورش يفتخر بهذا اللقب ويقول: \"أستاذي سماني به\".\n\n### رحلته إلى الإمام نافع\n\n رحل ورش من مصر إلى المدينة المنورة سنة (155 هـ) ليقرأ على الإمام نافع. فلما وصل إلى مسجد نافع، وجده مزدحماً بالقراء، فشفع له بعض أقارب نافع ليقرأ عليه. \n\n كان ورش حسن الصوت جداً، فقرأ على نافع ختمات عدة. وقيل إنه قرأ عليه أربع ختمات في شهر، ثم رجع إلى مصر وانتهت إليه رياسة الإقراء بها.",
  "u0-l4": "## ترجمة الإمام ورش\n\n### البطاقة الشخصية\n\n* **الاسم:** عثمان بن سعيد بن عبد الله، المصري، وقيل: القبطي، وقيل: مولى آل الزبير.\n \n* **الكنية:** أبو سعيد.\n \n* **اللقب:** ورش (وهو اللقب الذي اشتهر به).\n \n* **المولد:** وُلد في مصر سنة (110 هـ).\n \n* **الوفاة:** توفي بمصر سنة (197 هـ).\n\n### سبب تسميته بـ \"ورش\"\n\n ذكر العلماء أن الإمام نافعًا هو من لقبه بـ \"ورش\" لشدة بياضه (والورش شيء يصنع من اللبن). وقيل: لقصره وخفة حركته تشبيهاً بطائر يسمى الورشان. وكان الإمام ورش يفتخر بهذا اللقب ويقول: \"أستاذي سماني به\".\n\n### رحلته إلى الإمام نافع\n\n رحل ورش من مصر إلى المدينة المنورة سنة (155 هـ) ليقرأ على الإمام نافع. فلما وصل إلى مسجد نافع، وجده مزدحماً بالقراء، فشفع له بعض أقارب نافع ليقرأ عليه. \n\n كان ورش حسن الصوت جداً، فقرأ على نافع ختمات عدة. وقيل إنه قرأ عليه أربع ختمات في شهر، ثم رجع إلى مصر وانتهت إليه رياسة الإقراء بها.",
  "warsh-unit-0-u0-l5": "## إسناد رواية ورش عن نافع\n\n أخذ ورش القراءة عرضاً وتلاوة عن الإمام نافع في المدينة المنورة. وعاد إلى مصر، فأقرأ الناس هناك، فانتشرت روايته في مصر والمغرب والأندلس.\n\n### كيف وصلت الرواية من ورش إلى الشاطبي؟\n\nمن أهم الطرق التي نقلت لنا قراءة ورش هو طريق تلميذه **أبي يعقوب الأزرق**، وهو الطريق الذي اعتمده الإمام الشاطبي في منظومته.\n\n الإمام نافع المدني \n \n الإمام ورش \n \n أبو يعقوب الأزرق \n عنه أخذ أئمة القراءة، ومنهم: \n \n أبو بكر بن سيف \n \n أبو محمد النحاس \n \n أبو عمرو الداني (صاحب التيسير) \n \n الإمام الشاطبي (صاحب الحرز)",
  "u0-l5": "## إسناد رواية ورش عن نافع\n\n أخذ ورش القراءة عرضاً وتلاوة عن الإمام نافع في المدينة المنورة. وعاد إلى مصر، فأقرأ الناس هناك، فانتشرت روايته في مصر والمغرب والأندلس.\n\n### كيف وصلت الرواية من ورش إلى الشاطبي؟\n\nمن أهم الطرق التي نقلت لنا قراءة ورش هو طريق تلميذه **أبي يعقوب الأزرق**، وهو الطريق الذي اعتمده الإمام الشاطبي في منظومته.\n\n الإمام نافع المدني \n \n الإمام ورش \n \n أبو يعقوب الأزرق \n عنه أخذ أئمة القراءة، ومنهم: \n \n أبو بكر بن سيف \n \n أبو محمد النحاس \n \n أبو عمرو الداني (صاحب التيسير) \n \n الإمام الشاطبي (صاحب الحرز)",
  "warsh-unit-0-u0-l6": "## الشاطبي وحرز الأماني\n\n### من هو الإمام الشاطبي؟\n\n هو القاسم بن فيرُّه بن خلف بن أحمد الشاطبي الرعيني الأندلسي (538 هـ - 590 هـ). إمام كبير من أئمة القراءات، ضرير البصر، بصير البصيرة. وُلِد بشاطبة في الأندلس واستقر بمصر.\n\n### كتابه: حرز الأماني ووجه التهاني\n\n وتُعرف اختصاراً بـ **\"الشاطبية\"**. هي منظومة شعرية (قصيدة لامية) في علم القراءات السبع، تتكون من 1173 بيتاً.\n\n#### أصلها:\n\nنظم فيها كتاب \"التيسير في القراءات السبع\" للإمام أبي عمرو الداني، وزاد عليه بعض الأوجه (تسمى زيادات القصيد).\n\n#### مكانتها:\n\nتلقاها العلماء بالقبول، وصارت العمدة في تعلم القراءات السبع وإقرائها، وشُرحت عشرات الشروح.\n\n### \n 💡 \n فائدة للطالب\n\n في دراستنا لرواية ورش من هذا المنهج، سنعتمد على **\"الشاطبية\"** كمرجع أساسي في تقرير الأوجه والأحكام. وسنذكر أبيات الشاطبي كدليل وحجة لكل حكمندرسه. ولذلك يُنسب هذا الطريق في القراءة إلى \"الشاطبية\".",
  "u0-l6": "## الشاطبي وحرز الأماني\n\n### من هو الإمام الشاطبي؟\n\n هو القاسم بن فيرُّه بن خلف بن أحمد الشاطبي الرعيني الأندلسي (538 هـ - 590 هـ). إمام كبير من أئمة القراءات، ضرير البصر، بصير البصيرة. وُلِد بشاطبة في الأندلس واستقر بمصر.\n\n### كتابه: حرز الأماني ووجه التهاني\n\n وتُعرف اختصاراً بـ **\"الشاطبية\"**. هي منظومة شعرية (قصيدة لامية) في علم القراءات السبع، تتكون من 1173 بيتاً.\n\n#### أصلها:\n\nنظم فيها كتاب \"التيسير في القراءات السبع\" للإمام أبي عمرو الداني، وزاد عليه بعض الأوجه (تسمى زيادات القصيد).\n\n#### مكانتها:\n\nتلقاها العلماء بالقبول، وصارت العمدة في تعلم القراءات السبع وإقرائها، وشُرحت عشرات الشروح.\n\n### \n 💡 \n فائدة للطالب\n\n في دراستنا لرواية ورش من هذا المنهج، سنعتمد على **\"الشاطبية\"** كمرجع أساسي في تقرير الأوجه والأحكام. وسنذكر أبيات الشاطبي كدليل وحجة لكل حكمندرسه. ولذلك يُنسب هذا الطريق في القراءة إلى \"الشاطبية\".",
  "warsh-unit-0-u0-l7": "## ما معنى \"ورش عن نافع من طريق الشاطبية\"؟\n\n الآن، وبعد أن عرفنا مصطلحات (القراءة، الرواية، الطريق) وتراجم الأئمة، يمكننا تفكيك هذا العنوان الذي يمثل منهجنا:\n\n نافع\n\n**الإمام صاحب القراءة:** وهو الذي نُسبت إليه القراءة جملةً، وهو أحد القراء السبعة.\n\n ورش (عن نافع)\n\n**الراوي عن الإمام:** نقل اختيارات نافع ورواها عنه، مع ما اختص به ورش من الأصول والفرش.\n\n من طريق الشاطبية (الأزرق)\n\n**طريق نقل الرواية:** لورش طرق كثيرة عنه (كالأزرق والأصبهاني). الشاطبية اعتمدت طريق **أبي يعقوب الأزرق**.\n\nفكل ما في الشاطبية لورش هو من طريق الأزرق. وإذا أُطلق \"ورش من طريق الشاطبية\" قُصد به طريق الأزرق المدوّن في حرز الأماني للتيسير.\n\n### ⚠️ تنبيه منهجي هام جداً\n\n التزامنا بـ \"طريق الشاطبية\" يعني أننا **لا يجوز** أن نقرأ بوجه لورش لم يذكره الشاطبي أو لم يُنقل من طريق الأزرق من هذا الكتاب، حتى وإن صح ذلك الوجه من كتاب آخر (مثل \"طيبة النشر\"). الخلط بين الطرق يسمى \"التركيب\"، وهو معيب عند أهل الأداء.",
  "u0-l7": "## ما معنى \"ورش عن نافع من طريق الشاطبية\"؟\n\n الآن، وبعد أن عرفنا مصطلحات (القراءة، الرواية، الطريق) وتراجم الأئمة، يمكننا تفكيك هذا العنوان الذي يمثل منهجنا:\n\n نافع\n\n**الإمام صاحب القراءة:** وهو الذي نُسبت إليه القراءة جملةً، وهو أحد القراء السبعة.\n\n ورش (عن نافع)\n\n**الراوي عن الإمام:** نقل اختيارات نافع ورواها عنه، مع ما اختص به ورش من الأصول والفرش.\n\n من طريق الشاطبية (الأزرق)\n\n**طريق نقل الرواية:** لورش طرق كثيرة عنه (كالأزرق والأصبهاني). الشاطبية اعتمدت طريق **أبي يعقوب الأزرق**.\n\nفكل ما في الشاطبية لورش هو من طريق الأزرق. وإذا أُطلق \"ورش من طريق الشاطبية\" قُصد به طريق الأزرق المدوّن في حرز الأماني للتيسير.\n\n### ⚠️ تنبيه منهجي هام جداً\n\n التزامنا بـ \"طريق الشاطبية\" يعني أننا **لا يجوز** أن نقرأ بوجه لورش لم يذكره الشاطبي أو لم يُنقل من طريق الأزرق من هذا الكتاب، حتى وإن صح ذلك الوجه من كتاب آخر (مثل \"طيبة النشر\"). الخلط بين الطرق يسمى \"التركيب\"، وهو معيب عند أهل الأداء.",
  "warsh-unit-1-u1-l1": "## \n \n المد المتصل والمنفصل\n\n المد هو إطالة الصوت بحرف من حروف المد (الألف، الواو، الياء) عند وجود سبب لذلك، كالهمز أو السكون.\n في هذا الدرس سنتعرف على مذهب الإمام ورش في المدين المتصل والمنفصل.\n\n### القاعدة عند ورش من طريق الشاطبية\n\n يقرأ ورش بإشباع (تطويل) المد المتصل والمنفصل بمقدار 6 حركات قولاً واحداً.\n\n#### المد المتصل\n\nأن يجتمع حرف المد والهمز في كلمة واحدة.\n\n ﴿ جَآءَ ﴾ \n\n ﴿ سُوٓءَ ﴾ \n\n ﴿ سِيٓءَتۡ ﴾ \n\n#### المد المنفصل\n\nأن يكون حرف المد في آخر الكلمة والهمز في أول الكلمة التالية.\n\n ﴿ بِمَآ أُنزِلَ ﴾ \n\n ﴿ قُوٓاْ أَنفُسَكُمۡ ﴾ \n\n ﴿ فِيٓ أَنفُسِكُمۡ ﴾ \n\n### \n \n الشاهد من الشاطبية\n\n إِذَا أَلِفٌ أَوْ يَاؤُهَا بَعْدَ كَسْرَةٍ * أَوِ الْوَاوُ عَنْ ضَمٍّ لَقِيَ الْهَمْزَ طُوِّلاَ\n\n فَإِنْ يَنْفَصِلْ فَالْقَصْرُ بَادَرَه طَالِبًا * بِخُلْفِهِماَ يُرْوِيكَ دَرًّا وَمُخْضَلاَ\n\n * ملحوظة: لم يُذكر ورش مع أصحاب القصر أو التوسط، فبقي على الأصل وهو \"الطول\" (6 حركات) كالإمام حمزة.",
  "u1-l1": "## \n \n المد المتصل والمنفصل\n\n المد هو إطالة الصوت بحرف من حروف المد (الألف، الواو، الياء) عند وجود سبب لذلك، كالهمز أو السكون.\n في هذا الدرس سنتعرف على مذهب الإمام ورش في المدين المتصل والمنفصل.\n\n### القاعدة عند ورش من طريق الشاطبية\n\n يقرأ ورش بإشباع (تطويل) المد المتصل والمنفصل بمقدار 6 حركات قولاً واحداً.\n\n#### المد المتصل\n\nأن يجتمع حرف المد والهمز في كلمة واحدة.\n\n ﴿ جَآءَ ﴾ \n\n ﴿ سُوٓءَ ﴾ \n\n ﴿ سِيٓءَتۡ ﴾ \n\n#### المد المنفصل\n\nأن يكون حرف المد في آخر الكلمة والهمز في أول الكلمة التالية.\n\n ﴿ بِمَآ أُنزِلَ ﴾ \n\n ﴿ قُوٓاْ أَنفُسَكُمۡ ﴾ \n\n ﴿ فِيٓ أَنفُسِكُمۡ ﴾ \n\n### \n \n الشاهد من الشاطبية\n\n إِذَا أَلِفٌ أَوْ يَاؤُهَا بَعْدَ كَسْرَةٍ * أَوِ الْوَاوُ عَنْ ضَمٍّ لَقِيَ الْهَمْزَ طُوِّلاَ\n\n فَإِنْ يَنْفَصِلْ فَالْقَصْرُ بَادَرَه طَالِبًا * بِخُلْفِهِماَ يُرْوِيكَ دَرًّا وَمُخْضَلاَ\n\n * ملحوظة: لم يُذكر ورش مع أصحاب القصر أو التوسط، فبقي على الأصل وهو \"الطول\" (6 حركات) كالإمام حمزة.",
  "warsh-unit-1-u1-l2": "## \n \n مد البدل\n\n من أهم الأبواب التي ينفرد بها الإمام ورش من طريق الشاطبية هو (مد البدل)، حيث اختصه الشاطبي بأحكام دقيقة تميزه عن بقية القراء.\n\n### \n \n تعريف مد البدل\n\n هو كل همز ممدود، أي أن يتقدم الهمز على حرف المد في كلمة واحدة، وليس بعد حرف المد همز أو سكون.\n\n### مذهب ورش في البدل\n\n لورش في البدل من طريق الشاطبية ثلاثة أوجه جائزة:\n\n القصر \n حركتان (2) \n\n التوسط \n 4 حركات \n (وهو الوجه المقدم أداءً في كثير من المدارس) \n\n الإشباع \n 6 حركات \n\n### أمثلة بالرسم العثماني\n\n الهمز مع الألف \n ﴿ ءَامَنُواْ ﴾ \n\n الهمز مع الواو \n ﴿ أُوتُواْ ﴾ \n\n الهمز مع الياء \n ﴿ إِيمَٰنًا ﴾ \n\n### \n \n الشاهد من الشاطبية\n\n وَمَا بَعْدَ هَمْزٍ ثَابِتٍ أَوْ مُغَيَّرٍ * فَقَصْرٌ وَقَدْ يُرْوَى لِوَرْشٍ مُطَوَّلاَ\n\n وَوَسَّطَهُ قَوْمٌ كَآمَنَ هؤُلاَ * ءَالِهَةً آتَى لِلْإِيمَانِ مُثِّلاَ",
  "u1-l2": "## \n \n مد البدل\n\n من أهم الأبواب التي ينفرد بها الإمام ورش من طريق الشاطبية هو (مد البدل)، حيث اختصه الشاطبي بأحكام دقيقة تميزه عن بقية القراء.\n\n### \n \n تعريف مد البدل\n\n هو كل همز ممدود، أي أن يتقدم الهمز على حرف المد في كلمة واحدة، وليس بعد حرف المد همز أو سكون.\n\n### مذهب ورش في البدل\n\n لورش في البدل من طريق الشاطبية ثلاثة أوجه جائزة:\n\n القصر \n حركتان (2) \n\n التوسط \n 4 حركات \n (وهو الوجه المقدم أداءً في كثير من المدارس) \n\n الإشباع \n 6 حركات \n\n### أمثلة بالرسم العثماني\n\n الهمز مع الألف \n ﴿ ءَامَنُواْ ﴾ \n\n الهمز مع الواو \n ﴿ أُوتُواْ ﴾ \n\n الهمز مع الياء \n ﴿ إِيمَٰنًا ﴾ \n\n### \n \n الشاهد من الشاطبية\n\n وَمَا بَعْدَ هَمْزٍ ثَابِتٍ أَوْ مُغَيَّرٍ * فَقَصْرٌ وَقَدْ يُرْوَى لِوَرْشٍ مُطَوَّلاَ\n\n وَوَسَّطَهُ قَوْمٌ كَآمَنَ هؤُلاَ * ءَالِهَةً آتَى لِلْإِيمَانِ مُثِّلاَ",
  "warsh-unit-1-u1-l3": "## \n \n استثناءات مد البدل\n\n رغم أن القاعدة عند ورش هي جواز الأوجه الثلاثة في البدل، إلا أن هناك كلمات وحالات استثناها الرواة، ولا يجوز فيها لورش إلا القصر (حركتان) فقط.\n\n#### 1. أن يسبق الهمز ساكن صحيح متصل\n\nإذا جاء قبل الهمزة حرف ساكن سكوناً صحيحاً (ليس حرف مد) في نفس الكلمة.\n\n ﴿ قُرۡءَان ﴾ \n ﴿ مَسۡـُٔولًا ﴾ \n\n#### 2. همزة الوصل عند الابتداء\n\nإذا كان الهمز مبدلاً من همزة وصل عند الابتداء بالكلمة.\n\n ﴿ ٱئۡتِ ﴾ تُقرأ ابتداءً:﴾ إِيتِ \n\n#### 3. كلمة (يؤاخذ) ومشتقاتها\n\nحيثما وردت في القرآن الكريم.\n\n ﴿ يُؤَاخِذُ ﴾ \n\n#### 4. كلمة (إسرائيل)\n\nيُقصد الياء التي بعد الهمزة، فيها القصر فقط لورش.\n\n ﴿ إِسۡرَٰٓءِيل ﴾ \n\n### \n \n الشاهد من الشاطبية\n\n سِوَى يَاءِ إِسْرَائِيلَ أَوْ بَعْدَ سَاكِنٍ * صَحِيحٍ كَقُرْآنٍ وَمَسْئُولاً اسْأَلاَ\n\n وَمَا بَعْدَ هَمْزِ الْوَصْلِ إِيتِ وَبَعْضُهُمْ * يُؤَاخِذُكُمُ الآنَ مُسْتَفْهِماً تَلاَ",
  "u1-l3": "## \n \n استثناءات مد البدل\n\n رغم أن القاعدة عند ورش هي جواز الأوجه الثلاثة في البدل، إلا أن هناك كلمات وحالات استثناها الرواة، ولا يجوز فيها لورش إلا القصر (حركتان) فقط.\n\n#### 1. أن يسبق الهمز ساكن صحيح متصل\n\nإذا جاء قبل الهمزة حرف ساكن سكوناً صحيحاً (ليس حرف مد) في نفس الكلمة.\n\n ﴿ قُرۡءَان ﴾ \n ﴿ مَسۡـُٔولًا ﴾ \n\n#### 2. همزة الوصل عند الابتداء\n\nإذا كان الهمز مبدلاً من همزة وصل عند الابتداء بالكلمة.\n\n ﴿ ٱئۡتِ ﴾ تُقرأ ابتداءً:﴾ إِيتِ \n\n#### 3. كلمة (يؤاخذ) ومشتقاتها\n\nحيثما وردت في القرآن الكريم.\n\n ﴿ يُؤَاخِذُ ﴾ \n\n#### 4. كلمة (إسرائيل)\n\nيُقصد الياء التي بعد الهمزة، فيها القصر فقط لورش.\n\n ﴿ إِسۡرَٰٓءِيل ﴾ \n\n### \n \n الشاهد من الشاطبية\n\n سِوَى يَاءِ إِسْرَائِيلَ أَوْ بَعْدَ سَاكِنٍ * صَحِيحٍ كَقُرْآنٍ وَمَسْئُولاً اسْأَلاَ\n\n وَمَا بَعْدَ هَمْزِ الْوَصْلِ إِيتِ وَبَعْضُهُمْ * يُؤَاخِذُكُمُ الآنَ مُسْتَفْهِماً تَلاَ",
  "warsh-unit-1-u1-l4": "## \n \n مد اللين المهموز\n\n### تعريف اللين المهموز\n\n هو أن تقع الواو أو الياء الساكنتان المفتوح ما قبلهما، وبعدهما همزة في كلمة واحدة.\n\n#### مثال الياء\n\n ﴿ شَيۡءٖ ﴾ \n\n#### مثال الواو\n\n ﴿ سَوۡءَةَ ﴾ \n\n### مذهب ورش فيه\n\n لورش في مد اللين المهموز وجهان فقط من طريق الشاطبية (وصلاً ووقفاً):\n\n التوسط \n 4 حركات \n\n الإشباع \n 6 حركات \n\n### \n \n مستثنيات اللين المهموز\n\nاستُثني لورش كلمتان لا مد فيهما (تُقرأ بالقصر - حركتان فقط):\n\n ﴿ مَوۡئِلًا ﴾ (الكهف) \n ﴿ ٱلۡمَوۡءُۥدَةُ ﴾ (التكوير - الواو الأولى) \n\n### \n \n الشاهد من الشاطبية\n\n وَإِنْ تَسْكُنِ الْيَا بَيْنَ فَتْحٍ وَهَمْزَةٍ * بِكِلْمَةٍ أَوْ وَاوٌ فَوَجْهَانِ جُمِّلاَ\n\n بِطُولٍ وَقَصْرٍ وَصْلُ وَرْشٍ وَوَقْفُهُ * وَعَنْ كُلٍّ الْمَوْءُودَةُ اقْصُرْ وَمَوْئِلاَ\n\n * ملاحظة: مصطلح \"قصر\" في هذا البيت يُقصد به \"التوسط\" (4 حركات) بالنسبة للطول (6)، لأن اللين لا مد فيه أصلاً.",
  "u1-l4": "## \n \n مد اللين المهموز\n\n### تعريف اللين المهموز\n\n هو أن تقع الواو أو الياء الساكنتان المفتوح ما قبلهما، وبعدهما همزة في كلمة واحدة.\n\n#### مثال الياء\n\n ﴿ شَيۡءٖ ﴾ \n\n#### مثال الواو\n\n ﴿ سَوۡءَةَ ﴾ \n\n### مذهب ورش فيه\n\n لورش في مد اللين المهموز وجهان فقط من طريق الشاطبية (وصلاً ووقفاً):\n\n التوسط \n 4 حركات \n\n الإشباع \n 6 حركات \n\n### \n \n مستثنيات اللين المهموز\n\nاستُثني لورش كلمتان لا مد فيهما (تُقرأ بالقصر - حركتان فقط):\n\n ﴿ مَوۡئِلًا ﴾ (الكهف) \n ﴿ ٱلۡمَوۡءُۥدَةُ ﴾ (التكوير - الواو الأولى) \n\n### \n \n الشاهد من الشاطبية\n\n وَإِنْ تَسْكُنِ الْيَا بَيْنَ فَتْحٍ وَهَمْزَةٍ * بِكِلْمَةٍ أَوْ وَاوٌ فَوَجْهَانِ جُمِّلاَ\n\n بِطُولٍ وَقَصْرٍ وَصْلُ وَرْشٍ وَوَقْفُهُ * وَعَنْ كُلٍّ الْمَوْءُودَةُ اقْصُرْ وَمَوْئِلاَ\n\n * ملاحظة: مصطلح \"قصر\" في هذا البيت يُقصد به \"التوسط\" (4 حركات) بالنسبة للطول (6)، لأن اللين لا مد فيه أصلاً.",
  "warsh-unit-1-u1-l5": "## \n \n اجتماع البدل مع اللين المهموز\n\n إذا اجتمع مد البدل مع مد اللين المهموز في تلاوة واحدة، فلا يجوز ضرب جميع الأوجه ببعضها، بل هناك أوجه مقروء بها (محررة) وأوجه ممتنعة.\n\n### جدول الأوجه الجائزة لورش\n\n وجه البدل \n وجه اللين المهموز \n الحكم \n\n قصر (2) \n توسط (4) \n جائز \n\n توسط (4) \n توسط (4) \n جائز \n\n إشباع (6) \n توسط (4) \n جائز \n\n إشباع (6) \n إشباع (6) \n جائز \n\n### \n \n الخلاصة\n\n* اللين المهموز يُقرأ بـ التوسط (4) على جميع أوجه البدل (2، 4، 6).\n \n* اللين المهموز يُقرأ بـ الإشباع (6) فقط إذا قُرئ البدل بـ الإشباع (6).\n \n* مجموع الأوجه الجائزة: 4 أوجه .",
  "u1-l5": "## \n \n اجتماع البدل مع اللين المهموز\n\n إذا اجتمع مد البدل مع مد اللين المهموز في تلاوة واحدة، فلا يجوز ضرب جميع الأوجه ببعضها، بل هناك أوجه مقروء بها (محررة) وأوجه ممتنعة.\n\n### جدول الأوجه الجائزة لورش\n\n وجه البدل \n وجه اللين المهموز \n الحكم \n\n قصر (2) \n توسط (4) \n جائز \n\n توسط (4) \n توسط (4) \n جائز \n\n إشباع (6) \n توسط (4) \n جائز \n\n إشباع (6) \n إشباع (6) \n جائز \n\n### \n \n الخلاصة\n\n* اللين المهموز يُقرأ بـ التوسط (4) على جميع أوجه البدل (2، 4، 6).\n \n* اللين المهموز يُقرأ بـ الإشباع (6) فقط إذا قُرئ البدل بـ الإشباع (6).\n \n* مجموع الأوجه الجائزة: 4 أوجه .",
  "warsh-unit-2-u2-l1": "## \n \n مقدمة في الهمزتين من كلمة\n\n الهمزتان من كلمة هما همزتا قطع تلاصقتا في كلمة واحدة، الأولى منهما مفتوحة دائماً (وهي همزة الاستفهام غالباً)، والثانية إما مفتوحة، أو مكسورة، أو مضمومة.\n\n### أنواع الهمزتين من كلمة\n\n* المفتوحتان: مثل ﴿ ءَأَنذَرۡتَهُمۡ ﴾ \n \n* المفتوحة فمكسورة: مثل ﴿ أَءِنَّكُمۡ ﴾ \n \n* المفتوحة فمضمومة: مثل ﴿ أَءُنَبِّئُكُم ﴾ \n\n### القاعدة العامة لورش\n\n إذا اجتمعت همزتا قطع في كلمة واحدة، فإن الإمام ورش يقرأ بتحقيق الهمزة الأولى (لأنها همزة استفهام)، ويغير الهمزة الثانية. والتغيير يكون إما بالتسهيل أو الإبدال (حسب نوع الهمزة).",
  "u2-l1": "## \n \n مقدمة في الهمزتين من كلمة\n\n الهمزتان من كلمة هما همزتا قطع تلاصقتا في كلمة واحدة، الأولى منهما مفتوحة دائماً (وهي همزة الاستفهام غالباً)، والثانية إما مفتوحة، أو مكسورة، أو مضمومة.\n\n### أنواع الهمزتين من كلمة\n\n* المفتوحتان: مثل ﴿ ءَأَنذَرۡتَهُمۡ ﴾ \n \n* المفتوحة فمكسورة: مثل ﴿ أَءِنَّكُمۡ ﴾ \n \n* المفتوحة فمضمومة: مثل ﴿ أَءُنَبِّئُكُم ﴾ \n\n### القاعدة العامة لورش\n\n إذا اجتمعت همزتا قطع في كلمة واحدة، فإن الإمام ورش يقرأ بتحقيق الهمزة الأولى (لأنها همزة استفهام)، ويغير الهمزة الثانية. والتغيير يكون إما بالتسهيل أو الإبدال (حسب نوع الهمزة).",
  "warsh-unit-2-u2-l2": "## \n \n الهمزتان المفتوحتان\n\n إذا كانت الهمزة الثانية مفتوحة (بعد الأولى المفتوحة)، ففيها لورش وجهان جائزان، والوجهان مقروء بهما.\n\n### 1. التسهيل\n\nتسهيل الهمزة الثانية بين الهمزة والألف.\n\n ﴿ ءَأَنذَرۡتَهُمۡ ﴾ \n\n### 2. الإبدال\n\nإبدال الهمزة الثانية ألفاً خالصة (حرف مد).\n\n ﴿ ءَآنذَرۡتَهُمۡ ﴾ \n\n### \n \n ملاحظة مهمة في وجه الإبدال\n\n إذا أبدلنا الهمزة الثانية ألفاً، ننظر إلى الحرف الذي بعدها:\n\n* إذا كان الحرف الذي بعدها ساكناً، تُمد الألف 6 حركات (إشباع) من باب المد اللازم، مثل: ﴿ ءَأَنذَرۡتَهُمۡ ﴾.\n \n* إذا كان الحرف الذي بعدها متحركاً، تُمد الألف حركتين (قصر) من باب المد الطبيعي، مثل: ﴿ ءَأَلِدُ ﴾ ⬅ ﴿ ءَالِدُ ﴾.\n\n### \n \n الشاهد من الشاطبية\n\n وَتَسْهِيلُ أُخْرَى هَمْزَتَيْنِ بِكِلْمَةٍ * سَمَا وَبِذَاتِ الْفَتْحِ خُلْفٌ لِتَجْمُلاَ\n\n وَقُلْ أَلِفاً عَنْ أَهْلِ مِصْرَ تَبَدَّلَتْ * لِوَرْشٍ وَفِي بَغْدَادَ يُرْوَى مُسَهَّلاَ",
  "u2-l2": "## \n \n الهمزتان المفتوحتان\n\n إذا كانت الهمزة الثانية مفتوحة (بعد الأولى المفتوحة)، ففيها لورش وجهان جائزان، والوجهان مقروء بهما.\n\n### 1. التسهيل\n\nتسهيل الهمزة الثانية بين الهمزة والألف.\n\n ﴿ ءَأَنذَرۡتَهُمۡ ﴾ \n\n### 2. الإبدال\n\nإبدال الهمزة الثانية ألفاً خالصة (حرف مد).\n\n ﴿ ءَآنذَرۡتَهُمۡ ﴾ \n\n### \n \n ملاحظة مهمة في وجه الإبدال\n\n إذا أبدلنا الهمزة الثانية ألفاً، ننظر إلى الحرف الذي بعدها:\n\n* إذا كان الحرف الذي بعدها ساكناً، تُمد الألف 6 حركات (إشباع) من باب المد اللازم، مثل: ﴿ ءَأَنذَرۡتَهُمۡ ﴾.\n \n* إذا كان الحرف الذي بعدها متحركاً، تُمد الألف حركتين (قصر) من باب المد الطبيعي، مثل: ﴿ ءَأَلِدُ ﴾ ⬅ ﴿ ءَالِدُ ﴾.\n\n### \n \n الشاهد من الشاطبية\n\n وَتَسْهِيلُ أُخْرَى هَمْزَتَيْنِ بِكِلْمَةٍ * سَمَا وَبِذَاتِ الْفَتْحِ خُلْفٌ لِتَجْمُلاَ\n\n وَقُلْ أَلِفاً عَنْ أَهْلِ مِصْرَ تَبَدَّلَتْ * لِوَرْشٍ وَفِي بَغْدَادَ يُرْوَى مُسَهَّلاَ",
  "warsh-unit-2-u2-l3": "## \n \n المفتوحة فمكسورة\n\n النوع الثاني هو أن تكون الهمزة الأولى مفتوحة والثانية مكسورة.\n\n### حكمها لورش\n\n فيها وجه واحد فقط وهو: التسهيل .\n\nتُسهل الهمزة الثانية بين الهمزة والياء.\n\n مثال (أَئِنَّكُمْ) \n ﴿ أَءِنَّكُمۡ ﴾ \n\n مثال (أَئِذَا) \n ﴿ أَءِذَا ﴾",
  "u2-l3": "## \n \n المفتوحة فمكسورة\n\n النوع الثاني هو أن تكون الهمزة الأولى مفتوحة والثانية مكسورة.\n\n### حكمها لورش\n\n فيها وجه واحد فقط وهو: التسهيل .\n\nتُسهل الهمزة الثانية بين الهمزة والياء.\n\n مثال (أَئِنَّكُمْ) \n ﴿ أَءِنَّكُمۡ ﴾ \n\n مثال (أَئِذَا) \n ﴿ أَءِذَا ﴾",
  "warsh-unit-2-u2-l4": "## \n \n المفتوحة فمضمومة\n\n النوع الثالث هو أن تكون الهمزة الأولى مفتوحة والثانية مضمومة. وقد وردت في القرآن الكريم في ثلاثة مواضع فقط.\n\n### حكمها لورش\n\n فيها وجه واحد فقط وهو: التسهيل .\n\nتُسهل الهمزة الثانية بين الهمزة والواو.\n\n في سورة آل عمران \n ﴿ قُلۡ أَءُنَبِّئُكُم ﴾ \n\n في سورة ص \n ﴿ أَءُنزِلَ عَلَيۡهِ ﴾ \n\n في سورة القمر \n ﴿ أَءُلۡقِيَ ٱلذِّكۡرُ ﴾",
  "u2-l4": "## \n \n المفتوحة فمضمومة\n\n النوع الثالث هو أن تكون الهمزة الأولى مفتوحة والثانية مضمومة. وقد وردت في القرآن الكريم في ثلاثة مواضع فقط.\n\n### حكمها لورش\n\n فيها وجه واحد فقط وهو: التسهيل .\n\nتُسهل الهمزة الثانية بين الهمزة والواو.\n\n في سورة آل عمران \n ﴿ قُلۡ أَءُنَبِّئُكُم ﴾ \n\n في سورة ص \n ﴿ أَءُنزِلَ عَلَيۡهِ ﴾ \n\n في سورة القمر \n ﴿ أَءُلۡقِيَ ٱلذِّكۡرُ ﴾",
  "warsh-unit-3-u3-l1": "## \n \n الهمزتان المتفقتان في الحركة\n\n الهمزتان من كلمتين هما همزتا قطع متلاصقتان، تقع الأولى في آخر الكلمة الأولى، وتقع الثانية في أول الكلمة التي تليها. وينقسم هذا الباب إلى المتفقتين في الحركة والمختلفتين فيها.\n\n### \n \n من الشاطبية (بشرح الدكتور صبري سلامة في الوسيط)\n\n وَأَسْقَطَ الاُولَى فِي اتِّفَاقِهِمَا مَعًا ... إِذَا كَانَتَا مِنْ كِلْمَتَيْنِ فَتَى الْعُلاَ \n ... وَالاُخْرَى كَمَدٍّ عِنْدَ وَرْشٍ وَقُنْبُلٍ ... وَقَدْ قِيلَ مَحْضُ الْمَدِّ عَنْهَا تَبَدَّلاَ\n\n **شرح ما بين السطور:** يوضح الدكتور صبري سلامة أن الإمام ورشاً يتعامل مع الهمزة **الثانية** (وليست الأولى كأبي عمرو) بالتغيير إذا اتفقت الهمزتان في الحركة (مفتوحتان، مكسورتان، مضمومتان).\n\n#### أوجه ورش في الهمزتين المتفقتين\n\nلورش في الهمزة الثانية من المتفقتين وجهان، والمقدم هو الإبدال:\n\n* \n **1. الإبدال (وهو المقدم أداءً):**\n \n يبدل الهمزة الثانية حرف مد مجانس لحركة الهمزة الأولى.\n \n **المفتوحتان:** (جاءَ أَمرنا) تبدل ألفاً. وإذا كان بعدها ساكن تمد 6 حركات (جاءَ اْمرنا).\n \n* **المكسورتان:** (هؤُلاءِ إِن) تبدل ياءً.\n \n* **المضمومتان:** (أولياءُ أُولئك) تبدل واواً.\n\n ملاحظة من الوسيط: الإبدال هو محض المد، ويراعى في مقدار المد حركة الحرف الذي بعد المبدل (إن كان ساكناً مد إشباعاً، وإن كان متحركاً مد قصراً). \n\n* \n **2. التسهيل:**\n \n تسهيل الهمزة الثانية بين الهمزة وحرف المد المجانس لحركتها (بين الهمزة والألف، أو الياء، أو الواو).",
  "u3-l1": "## \n \n الهمزتان المتفقتان في الحركة\n\n الهمزتان من كلمتين هما همزتا قطع متلاصقتان، تقع الأولى في آخر الكلمة الأولى، وتقع الثانية في أول الكلمة التي تليها. وينقسم هذا الباب إلى المتفقتين في الحركة والمختلفتين فيها.\n\n### \n \n من الشاطبية (بشرح الدكتور صبري سلامة في الوسيط)\n\n وَأَسْقَطَ الاُولَى فِي اتِّفَاقِهِمَا مَعًا ... إِذَا كَانَتَا مِنْ كِلْمَتَيْنِ فَتَى الْعُلاَ \n ... وَالاُخْرَى كَمَدٍّ عِنْدَ وَرْشٍ وَقُنْبُلٍ ... وَقَدْ قِيلَ مَحْضُ الْمَدِّ عَنْهَا تَبَدَّلاَ\n\n **شرح ما بين السطور:** يوضح الدكتور صبري سلامة أن الإمام ورشاً يتعامل مع الهمزة **الثانية** (وليست الأولى كأبي عمرو) بالتغيير إذا اتفقت الهمزتان في الحركة (مفتوحتان، مكسورتان، مضمومتان).\n\n#### أوجه ورش في الهمزتين المتفقتين\n\nلورش في الهمزة الثانية من المتفقتين وجهان، والمقدم هو الإبدال:\n\n* \n **1. الإبدال (وهو المقدم أداءً):**\n \n يبدل الهمزة الثانية حرف مد مجانس لحركة الهمزة الأولى.\n \n **المفتوحتان:** (جاءَ أَمرنا) تبدل ألفاً. وإذا كان بعدها ساكن تمد 6 حركات (جاءَ اْمرنا).\n \n* **المكسورتان:** (هؤُلاءِ إِن) تبدل ياءً.\n \n* **المضمومتان:** (أولياءُ أُولئك) تبدل واواً.\n\n ملاحظة من الوسيط: الإبدال هو محض المد، ويراعى في مقدار المد حركة الحرف الذي بعد المبدل (إن كان ساكناً مد إشباعاً، وإن كان متحركاً مد قصراً). \n\n* \n **2. التسهيل:**\n \n تسهيل الهمزة الثانية بين الهمزة وحرف المد المجانس لحركتها (بين الهمزة والألف، أو الياء، أو الواو).",
  "warsh-unit-3-u3-l2": "## \n \n الهمزتان المختلفتان في الحركة\n\n### \n \n الشاهد من الشاطبية (مع شرح الوسيط)\n\n وَتَسْهِيلُ الاُخْرَى فِي اخْتِلاَفِهِما سَمَا ... تَفِيءَ إِلَى مَعْ جَاءَ أُمَّةً انْزِلاَ \n نَشَاءُ أَصَبْنَا وَالسَّمَاءِ أَوِ ائْتِنَا ... فَنَوْعَانِ قُلْ كَالْيَا وَكَالْوَاوِ سُهِّلاَ \n وَنَوْعَانِ مِنْهَا أُبْدِلاَ مِنْهُمَا وَقُلْ ... يَشَاءُ إِلَى كَالْيَاءِ أَقْيَسُ مَعْدِلاَ\n\n **شرح ما بين السطور:** يوضح د. صبري سلامة في \"الوسيط\" أن أهل سما (ومنهم نافع/ورش) يغيرون الهمزة **الثانية** في الهمزتين المختلفتين. والقاعدة تعتمد على مبدأ \"الفتح أضعف الحركات\"، فإذا تقدم الفتح سُهلت الثانية، وإذا تأخر الفتح أُبدلت، وإذا اجتمع الكسر والضم ففيها وجهان.\n\n#### النوع الأول: الأولى مفتوحة والثانية مكسورة/مضمومة\n\n**الحكم:** التسهيل فقط.\n\n* ﴿تَفِيءَ إِلَى﴾ تسهل الثانية بين الهمزة والياء.\n \n* ﴿جَاءَ أُمَّةً﴾ تسهل الثانية بين الهمزة والواو.\n\n#### النوع الثاني: الأولى مكسورة/مضمومة والثانية مفتوحة\n\n**الحكم:** الإبدال فقط.\n\n* ﴿نَشَاءُ أَصَبْنَا﴾ تبدل واواً خالصة مفتوحة (نشاءُ وَصبنا).\n \n* ﴿السَّمَاءِ أَوِ﴾ تبدل ياءً خالصة مفتوحة (السماءِ يَو).\n\n#### النوع الثالث: الأولى مضمومة والثانية مكسورة\n\n**الحكم:** الوجهان (التسهيل والإبدال واواً).\n\n* ﴿يَشَاءُ إِلَى﴾ فيها التسهيل بين الهمزة والياء، والإبدال واواً مكسورة (يَشَاءُ وِلى). وقال الشاطبي: (كالياء أقيس معدلا) أي أن الإبدال واواً أقيس كما أشار شراح كصبري سلامة.",
  "u3-l2": "## \n \n الهمزتان المختلفتان في الحركة\n\n### \n \n الشاهد من الشاطبية (مع شرح الوسيط)\n\n وَتَسْهِيلُ الاُخْرَى فِي اخْتِلاَفِهِما سَمَا ... تَفِيءَ إِلَى مَعْ جَاءَ أُمَّةً انْزِلاَ \n نَشَاءُ أَصَبْنَا وَالسَّمَاءِ أَوِ ائْتِنَا ... فَنَوْعَانِ قُلْ كَالْيَا وَكَالْوَاوِ سُهِّلاَ \n وَنَوْعَانِ مِنْهَا أُبْدِلاَ مِنْهُمَا وَقُلْ ... يَشَاءُ إِلَى كَالْيَاءِ أَقْيَسُ مَعْدِلاَ\n\n **شرح ما بين السطور:** يوضح د. صبري سلامة في \"الوسيط\" أن أهل سما (ومنهم نافع/ورش) يغيرون الهمزة **الثانية** في الهمزتين المختلفتين. والقاعدة تعتمد على مبدأ \"الفتح أضعف الحركات\"، فإذا تقدم الفتح سُهلت الثانية، وإذا تأخر الفتح أُبدلت، وإذا اجتمع الكسر والضم ففيها وجهان.\n\n#### النوع الأول: الأولى مفتوحة والثانية مكسورة/مضمومة\n\n**الحكم:** التسهيل فقط.\n\n* ﴿تَفِيءَ إِلَى﴾ تسهل الثانية بين الهمزة والياء.\n \n* ﴿جَاءَ أُمَّةً﴾ تسهل الثانية بين الهمزة والواو.\n\n#### النوع الثاني: الأولى مكسورة/مضمومة والثانية مفتوحة\n\n**الحكم:** الإبدال فقط.\n\n* ﴿نَشَاءُ أَصَبْنَا﴾ تبدل واواً خالصة مفتوحة (نشاءُ وَصبنا).\n \n* ﴿السَّمَاءِ أَوِ﴾ تبدل ياءً خالصة مفتوحة (السماءِ يَو).\n\n#### النوع الثالث: الأولى مضمومة والثانية مكسورة\n\n**الحكم:** الوجهان (التسهيل والإبدال واواً).\n\n* ﴿يَشَاءُ إِلَى﴾ فيها التسهيل بين الهمزة والياء، والإبدال واواً مكسورة (يَشَاءُ وِلى). وقال الشاطبي: (كالياء أقيس معدلا) أي أن الإبدال واواً أقيس كما أشار شراح كصبري سلامة.",
  "warsh-unit-4-u4-l1": "## \n \n الهمز الساكن المبدل\n\n### \n \n الشاهد من الشاطبية (مع شرح الوسيط)\n\n إِذَا سَكَنَتْ فَاءً مِنَ الْفِعْلِ هَمْزَةٌ ... فَوَرْشٌ يُرِيهَا حَرْفَ مَدٍّ مُبَدَّلاَ \n سِوَى جُمْلَةِ الايوَاءِ وَالْوَاوُ عَنْهُ إِنْ ... تَفَتَّحَ إِثْرَ الضَّمِّ نَحْوَ مُؤَجَّلاَ\n\n **شرح ما بين السطور:** يوضح د. صبري سلامة في \"الوسيط\" أن ورشاً يبدل كل همزة ساكنة وقعت (فاءً للكلمة) بحرف مد يجانس حركة ما قبلها، ويستثني من ذلك الكلمات المشتقة من مادة الإيواء (مثل مأوى، المأوى، مأواهم، فأووا، وتؤوي).\n\n#### شرح القاعدة والأمثلة\n\n قبلها فتح (تبدل ألفاً) \n\n* ﴿يَأْكُلُ﴾ تُقرأ: يَاكُلُ\n \n* ﴿فَأْتُوا﴾ تُقرأ: فَاتُوا\n \n* ﴿يَأْمُرُكُمْ﴾ تُقرأ: يَامُرُكُمْ\n\n قبلها كسر (تبدل ياءً) \n\n* ﴿بِئْسَ﴾ تُقرأ: بِيسَ\n \n* ﴿شِئْتَ﴾ تُقرأ: شِيتَ\n \n* ﴿الذِّئْبُ﴾ تُقرأ: الذِّيبُ\n\n قبلها ضم (تبدل واواً) \n\n* ﴿يُؤْمِنُ﴾ تُقرأ: يُومِنُ\n \n* ﴿الْمُؤْتَفِكَةِ﴾ تُقرأ: الْمُوتَفِكَةِ\n\n المستثنيات (مادة الإيواء) \n\n* ﴿المأوى﴾ ، ﴿مأواهم﴾ \n \n* ﴿فأووا﴾ ، ﴿تؤوي﴾ \n \n* تُقرأ بالهمز لورش بلا إبدال.\n\n كيف نعرف أنها فاء الكلمة؟ \n\n في علم الصرف تُوزن الكلمة بـ (فَعَلَ)، فإذا قابلت الهمزة حرف (الفاء) في الوزن فهي فاء الكلمة. مثال: يَأْكُل على وزن يَفْعُل، الهمزة تقابل الفاء فهي فاء الكلمة. أما (الرَّأْس) على وزن الفَعْل، فالهمزة تقابل العين فلا تبدل لورش.",
  "u4-l1": "## \n \n الهمز الساكن المبدل\n\n### \n \n الشاهد من الشاطبية (مع شرح الوسيط)\n\n إِذَا سَكَنَتْ فَاءً مِنَ الْفِعْلِ هَمْزَةٌ ... فَوَرْشٌ يُرِيهَا حَرْفَ مَدٍّ مُبَدَّلاَ \n سِوَى جُمْلَةِ الايوَاءِ وَالْوَاوُ عَنْهُ إِنْ ... تَفَتَّحَ إِثْرَ الضَّمِّ نَحْوَ مُؤَجَّلاَ\n\n **شرح ما بين السطور:** يوضح د. صبري سلامة في \"الوسيط\" أن ورشاً يبدل كل همزة ساكنة وقعت (فاءً للكلمة) بحرف مد يجانس حركة ما قبلها، ويستثني من ذلك الكلمات المشتقة من مادة الإيواء (مثل مأوى، المأوى، مأواهم، فأووا، وتؤوي).\n\n#### شرح القاعدة والأمثلة\n\n قبلها فتح (تبدل ألفاً) \n\n* ﴿يَأْكُلُ﴾ تُقرأ: يَاكُلُ\n \n* ﴿فَأْتُوا﴾ تُقرأ: فَاتُوا\n \n* ﴿يَأْمُرُكُمْ﴾ تُقرأ: يَامُرُكُمْ\n\n قبلها كسر (تبدل ياءً) \n\n* ﴿بِئْسَ﴾ تُقرأ: بِيسَ\n \n* ﴿شِئْتَ﴾ تُقرأ: شِيتَ\n \n* ﴿الذِّئْبُ﴾ تُقرأ: الذِّيبُ\n\n قبلها ضم (تبدل واواً) \n\n* ﴿يُؤْمِنُ﴾ تُقرأ: يُومِنُ\n \n* ﴿الْمُؤْتَفِكَةِ﴾ تُقرأ: الْمُوتَفِكَةِ\n\n المستثنيات (مادة الإيواء) \n\n* ﴿المأوى﴾ ، ﴿مأواهم﴾ \n \n* ﴿فأووا﴾ ، ﴿تؤوي﴾ \n \n* تُقرأ بالهمز لورش بلا إبدال.\n\n كيف نعرف أنها فاء الكلمة؟ \n\n في علم الصرف تُوزن الكلمة بـ (فَعَلَ)، فإذا قابلت الهمزة حرف (الفاء) في الوزن فهي فاء الكلمة. مثال: يَأْكُل على وزن يَفْعُل، الهمزة تقابل الفاء فهي فاء الكلمة. أما (الرَّأْس) على وزن الفَعْل، فالهمزة تقابل العين فلا تبدل لورش.",
  "warsh-unit-4-u4-l2": "## \n \n الهمز المتحرك المبدل\n\n### \n \n الشاهد من الشاطبية\n\n وَالْوَاوُ عَنْهُ إِنْ ... تَفَتَّحَ إِثْرَ الضَّمِّ نَحْوَ مُؤَجَّلاَ\n\n **الشرح (الوسيط):** إذا كانت الهمزة فاءً للكلمة، وكانت مفتوحة وما قبلها مضموم، فإن ورشاً يبدلها واواً مفتوحة.\n\n#### أمثلة الهمز المتحرك المبدل\n\n* ﴿مُؤَجَّلًا﴾ تقرأ: مَوَجَّلًا\n \n* ﴿مُؤَذِّنٌ﴾ تقرأ: مُوَذِّنٌ\n \n* ﴿الْمُؤَلَّفَةِ﴾ تقرأ: الْمُوَ‌لَّفَةِ\n\n* ﴿يُؤَخِّرُ﴾ تقرأ: يُوَخِّرُ\n \n* ﴿لَا تُؤَاخِذْنَا﴾ تقرأ: لَا تُوَاخِذْنَا\n\n **ملاحظة هامة:** يشترط أن تكون فاء الكلمة. فإذا كانت عين الكلمة مثل ﴿فُؤَاد﴾ فلا تبدل.",
  "u4-l2": "## \n \n الهمز المتحرك المبدل\n\n### \n \n الشاهد من الشاطبية\n\n وَالْوَاوُ عَنْهُ إِنْ ... تَفَتَّحَ إِثْرَ الضَّمِّ نَحْوَ مُؤَجَّلاَ\n\n **الشرح (الوسيط):** إذا كانت الهمزة فاءً للكلمة، وكانت مفتوحة وما قبلها مضموم، فإن ورشاً يبدلها واواً مفتوحة.\n\n#### أمثلة الهمز المتحرك المبدل\n\n* ﴿مُؤَجَّلًا﴾ تقرأ: مَوَجَّلًا\n \n* ﴿مُؤَذِّنٌ﴾ تقرأ: مُوَذِّنٌ\n \n* ﴿الْمُؤَلَّفَةِ﴾ تقرأ: الْمُوَ‌لَّفَةِ\n\n* ﴿يُؤَخِّرُ﴾ تقرأ: يُوَخِّرُ\n \n* ﴿لَا تُؤَاخِذْنَا﴾ تقرأ: لَا تُوَاخِذْنَا\n\n **ملاحظة هامة:** يشترط أن تكون فاء الكلمة. فإذا كانت عين الكلمة مثل ﴿فُؤَاد﴾ فلا تبدل.",
  "warsh-unit-4-u4-l3": "## \n \n الكلمات المخصوصة بالهمز المفرد\n\nهناك كلمات لا تدخل تحت القاعدة العامة للهمز (ليست فاء الكلمة)، لكن الإمام ورشاً اختصها بالإبدال حفظاً وأداءً.\n\n#### بِئْر / ذِئْب\n\nيبدل ورش همزتهما ياءً مدية (بِير، ذِيب)، وهي عين الكلمة وليست فاءها. (الشاهد: وبئر في طيئ...)\n\n#### بِئْسَ (وما اشتق منها)\n\nيبدلها ورش ياءً (بِيسَ). (الشاهد: وفي بئس ورش...)\n\n#### النَّسِيءُ\n\nفي سورة التوبة، يبدل الهمزة ياءً ويدغمها في الياء قبلها فتصير ياءً مشددة (النَّسِيُّ).\n\n#### كلمات أخرى\n\nمثل (رِئْياً) بسورة مريم تدغم ياءين (رِيّاً). ومثل (ضِيزَى) بسورة النجم تبدل ياء.",
  "u4-l3": "## \n \n الكلمات المخصوصة بالهمز المفرد\n\nهناك كلمات لا تدخل تحت القاعدة العامة للهمز (ليست فاء الكلمة)، لكن الإمام ورشاً اختصها بالإبدال حفظاً وأداءً.\n\n#### بِئْر / ذِئْب\n\nيبدل ورش همزتهما ياءً مدية (بِير، ذِيب)، وهي عين الكلمة وليست فاءها. (الشاهد: وبئر في طيئ...)\n\n#### بِئْسَ (وما اشتق منها)\n\nيبدلها ورش ياءً (بِيسَ). (الشاهد: وفي بئس ورش...)\n\n#### النَّسِيءُ\n\nفي سورة التوبة، يبدل الهمزة ياءً ويدغمها في الياء قبلها فتصير ياءً مشددة (النَّسِيُّ).\n\n#### كلمات أخرى\n\nمثل (رِئْياً) بسورة مريم تدغم ياءين (رِيّاً). ومثل (ضِيزَى) بسورة النجم تبدل ياء.",
  "warsh-unit-5-u5-l1": "## \n \n شروط النقل عند ورش\n\n النقل هو: نقل حركة همزة القطع إلى الحرف الساكن قبلها، مع حذف الهمزة. وهذا من أهم أصول الإمام ورش.\n\n### \n \n الشاهد من الشاطبية (بشرح الوسيط)\n\n وَحَرِّكْ لِوَرْشٍ كُلَّ سَاكِنٍ اخِرٍ ... صَحِيحٍ بِشَكْلِ الْهَمْزِ وَاحْذِفْهُ مُسْهِلاَ\n\n **شرح ما بين السطور:** ذكر د. صبري سلامة في الوسيط شروط النقل عند ورش مجموعة في هذا البيت:\n أن يكون الحرف المنقول إليه **ساكناً**، وأن يكون في **آخر الكلمة** (والهمزة في أول الكلمة الثانية)، وأن يكون الساكن **صحيحاً** (ليس حرف مد ولا ميم جمع).\n\n#### شروط النقل\n\n* أن يكون الحرف قبل الهمزة **ساكناً**.\n \n* أن يكون الساكن في **كلمة** والهمزة في الكلمة التي تليها (ساكن آخر).\n \n* أن يكون الساكن **صحيحاً** (وليس حرف مد كالواو والياء والألف).\n \n* ألا يكون الساكن **ميم جمع** (لأن لها حكماً خاصاً وهو الصلة).\n\n#### أمثلة تطبيقية\n\n* \n ﴿مَنْ آمَنَ﴾ \n &larr; \n ﴿مَنَ ามَنَ﴾ \n\n* \n ﴿قَدْ أَفْلَحَ﴾ \n &larr; \n ﴿قَدَ فْلَحَ﴾ \n\n* \n ﴿خَلَوْا إِلَى﴾ \n &larr; \n ﴿خَلَوِ لَى﴾",
  "u5-l1": "## \n \n شروط النقل عند ورش\n\n النقل هو: نقل حركة همزة القطع إلى الحرف الساكن قبلها، مع حذف الهمزة. وهذا من أهم أصول الإمام ورش.\n\n### \n \n الشاهد من الشاطبية (بشرح الوسيط)\n\n وَحَرِّكْ لِوَرْشٍ كُلَّ سَاكِنٍ اخِرٍ ... صَحِيحٍ بِشَكْلِ الْهَمْزِ وَاحْذِفْهُ مُسْهِلاَ\n\n **شرح ما بين السطور:** ذكر د. صبري سلامة في الوسيط شروط النقل عند ورش مجموعة في هذا البيت:\n أن يكون الحرف المنقول إليه **ساكناً**، وأن يكون في **آخر الكلمة** (والهمزة في أول الكلمة الثانية)، وأن يكون الساكن **صحيحاً** (ليس حرف مد ولا ميم جمع).\n\n#### شروط النقل\n\n* أن يكون الحرف قبل الهمزة **ساكناً**.\n \n* أن يكون الساكن في **كلمة** والهمزة في الكلمة التي تليها (ساكن آخر).\n \n* أن يكون الساكن **صحيحاً** (وليس حرف مد كالواو والياء والألف).\n \n* ألا يكون الساكن **ميم جمع** (لأن لها حكماً خاصاً وهو الصلة).\n\n#### أمثلة تطبيقية\n\n* \n ﴿مَنْ آمَنَ﴾ \n &larr; \n ﴿مَنَ ามَنَ﴾ \n\n* \n ﴿قَدْ أَفْلَحَ﴾ \n &larr; \n ﴿قَدَ فْلَحَ﴾ \n\n* \n ﴿خَلَوْا إِلَى﴾ \n &larr; \n ﴿خَلَوِ لَى﴾",
  "warsh-unit-5-u5-l2": "## \n \n النقل في (أل) التعريف\n\n لام (أل) التعريف الساكنة إذا جاء بعدها همزة قطع، فإن ورشاً ينقل حركة الهمزة إليها كالقاعدة العامة، لأن (أل) تعد في حكم الكلمة المنفصلة.\n\n الأصل \n ﴿الأَرْضِ﴾ \n \n بعد النقل لورش \n ﴿لَـرْضِ﴾ \n\n الأصل \n ﴿الإِيمَانِ﴾ \n \n بعد النقل لورش \n ﴿لِـيمَانِ﴾ \n\n#### \n الابتداء بالكلمة التي نُقلت حركتها\n\nعند الابتداء بكلمة مثل (الأرض)، فلك وجهان صحيحان مقروءٌ بهما:\n\n* **الاعتداد بالأصل:** الإتيان بهمزة الوصل مفتوحة (أَلَرْض).\n \n* **الاعتداد بالعارض:** البدء باللام المتحركة بحركة الهمزة دون همزة وصل (لَرْض).\n\nوالوجهان صحيحان معمول بهما في الأداء.",
  "u5-l2": "## \n \n النقل في (أل) التعريف\n\n لام (أل) التعريف الساكنة إذا جاء بعدها همزة قطع، فإن ورشاً ينقل حركة الهمزة إليها كالقاعدة العامة، لأن (أل) تعد في حكم الكلمة المنفصلة.\n\n الأصل \n ﴿الأَرْضِ﴾ \n \n بعد النقل لورش \n ﴿لَـرْضِ﴾ \n\n الأصل \n ﴿الإِيمَانِ﴾ \n \n بعد النقل لورش \n ﴿لِـيمَانِ﴾ \n\n#### \n الابتداء بالكلمة التي نُقلت حركتها\n\nعند الابتداء بكلمة مثل (الأرض)، فلك وجهان صحيحان مقروءٌ بهما:\n\n* **الاعتداد بالأصل:** الإتيان بهمزة الوصل مفتوحة (أَلَرْض).\n \n* **الاعتداد بالعارض:** البدء باللام المتحركة بحركة الهمزة دون همزة وصل (لَرْض).\n\nوالوجهان صحيحان معمول بهما في الأداء.",
  "warsh-unit-5-u5-l3": "## \n \n كتابيه إني (نقل وسكت)\n\n ﴿ فَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ فَيَقُولُ هَاؤُمُ اقْرَءُوا كِتَابِيَهْ ۝ إِنِّي ظَنَنْتُ أَنِّي مُلَاقٍ حِسَابِيَهْ ﴾\n\n في سورة الحاقة عند وصل (كتابيهْ) بـ (إني)، الهاء في (كتابيه) هاء سكت وهي ساكنة سكوناً أصلياً، وبعدها همزة قطع مكسورة. لورش فيها عند الوصل وجهان (ذكرهما ابن الجزري والعلماء):\n\n#### الوجه الأول: النقل\n\n تطبيقاً للقاعدة العامة (ساكن صحيح في آخر الكلمة + همزة قطع). تُنقل كسرة الهمزة إلى الهاء وتحذف الهمزة.\n\n ﴿كِتَابِيَهِ نِّي﴾ \n\n#### الوجه الثاني: السكت (وهو المقدم)\n\n السكت على هاء (كتابيهْ) سكتة لطيفة من غير تنفس ثم النطق بالهمزة (إني). والمقدم أداءً هو السكت للمحافظة على هاء السكت.\n\n ﴿كِتَابِيَهْ ... إِنِّي﴾ \n\n **تنبيه من الشاطبية (ونقل ردا...):** نقل عن الإمام نافع الرد (بترك النقل) في هذه الكلمة للمحافظة على هاء السكت التي بنيت على السكون، ولذلك جرى العمل بتقديم وجه السكت.",
  "u5-l3": "## \n \n كتابيه إني (نقل وسكت)\n\n ﴿ فَأَمَّا مَنْ أُوتِيَ كِتَابَهُ بِيَمِينِهِ فَيَقُولُ هَاؤُمُ اقْرَءُوا كِتَابِيَهْ ۝ إِنِّي ظَنَنْتُ أَنِّي مُلَاقٍ حِسَابِيَهْ ﴾\n\n في سورة الحاقة عند وصل (كتابيهْ) بـ (إني)، الهاء في (كتابيه) هاء سكت وهي ساكنة سكوناً أصلياً، وبعدها همزة قطع مكسورة. لورش فيها عند الوصل وجهان (ذكرهما ابن الجزري والعلماء):\n\n#### الوجه الأول: النقل\n\n تطبيقاً للقاعدة العامة (ساكن صحيح في آخر الكلمة + همزة قطع). تُنقل كسرة الهمزة إلى الهاء وتحذف الهمزة.\n\n ﴿كِتَابِيَهِ نِّي﴾ \n\n#### الوجه الثاني: السكت (وهو المقدم)\n\n السكت على هاء (كتابيهْ) سكتة لطيفة من غير تنفس ثم النطق بالهمزة (إني). والمقدم أداءً هو السكت للمحافظة على هاء السكت.\n\n ﴿كِتَابِيَهْ ... إِنِّي﴾ \n\n **تنبيه من الشاطبية (ونقل ردا...):** نقل عن الإمام نافع الرد (بترك النقل) في هذه الكلمة للمحافظة على هاء السكت التي بنيت على السكون، ولذلك جرى العمل بتقديم وجه السكت.",
  "warsh-unit-6-u6-l1": "## \n \n إدغام ذال (إذ) ودال (قد)\n\n### \n \n من الشاطبية\n\n نَعَمْ إِذْ تَمَشَّتْ زَيْنَبٌ صَالَ دَلُّهَا ... سَمِيَّ جَمَالٍ وَاصِلاً مَنْ تَوَصَّلاَ\n\n **مذهب ورش في (إذ):** يظهر ورش ذال (إذ) عند جميع حروفها الستة (التاء، الزاي، الصاد، الدال، السين، الجيم). فلا يدغمها في شيء منها.\n\n#### حكم دال (قد)\n\n وَقَدْ سَحَبَتْ ذَيْلاً ضَفَا ظَلَّ زَرْنَبٌ ... جَلاَتْهُ صَبَاهُ شَائِقاً وَمُعَلِّلاَ \n ... وَوَرْشٌ جَمِيعَ الْبَابِ كَانَ مُقَلِّلاَ (أي مقللاً للإدغام، فيظهر عند البعض ويدغم في البعض)\n\n أدغم الإمام ورش دال (قد) في حرفين فقط وأظهرها عند الباقي:\n\n* **الضاد:** ﴿فَقَد ضَّلَّ﴾ يدغم الدال في الضاد إدغاماً كاملاً.\n \n* **الظاء:** ﴿فَقَد ظَّلَمَ﴾ يدغم الدال في الظاء إدغاماً كاملاً.\n \n* أما عند بقية الحروف (السين، الذال، الزاي، الجيم، الصاد، الشين) فإنه **يظهرها**.",
  "u6-l1": "## \n \n إدغام ذال (إذ) ودال (قد)\n\n### \n \n من الشاطبية\n\n نَعَمْ إِذْ تَمَشَّتْ زَيْنَبٌ صَالَ دَلُّهَا ... سَمِيَّ جَمَالٍ وَاصِلاً مَنْ تَوَصَّلاَ\n\n **مذهب ورش في (إذ):** يظهر ورش ذال (إذ) عند جميع حروفها الستة (التاء، الزاي، الصاد، الدال، السين، الجيم). فلا يدغمها في شيء منها.\n\n#### حكم دال (قد)\n\n وَقَدْ سَحَبَتْ ذَيْلاً ضَفَا ظَلَّ زَرْنَبٌ ... جَلاَتْهُ صَبَاهُ شَائِقاً وَمُعَلِّلاَ \n ... وَوَرْشٌ جَمِيعَ الْبَابِ كَانَ مُقَلِّلاَ (أي مقللاً للإدغام، فيظهر عند البعض ويدغم في البعض)\n\n أدغم الإمام ورش دال (قد) في حرفين فقط وأظهرها عند الباقي:\n\n* **الضاد:** ﴿فَقَد ضَّلَّ﴾ يدغم الدال في الضاد إدغاماً كاملاً.\n \n* **الظاء:** ﴿فَقَد ظَّلَمَ﴾ يدغم الدال في الظاء إدغاماً كاملاً.\n \n* أما عند بقية الحروف (السين، الذال، الزاي، الجيم، الصاد، الشين) فإنه **يظهرها**.",
  "warsh-unit-6-u6-l2": "## \n \n تاء التأنيث ولام (هل) و(بل)\n\n#### تاء التأنيث الساكنة\n\n تأتي تاء التأنيث قبل ستة أحرف: السين، الثاء، الصاد، الزاي، الطاء، الجيم.\n\n **مذهب ورش:**\n أدغم ورش تاء التأنيث في الظاء فقط في قوله تعالى: ﴿كَانَت ظَّالِمَةً﴾ . وأظهرها عند باقي الحروف، مثل: ﴿حَصِرَتْ صُدُورُهُم﴾ ، ﴿نَضَجَتْ جُلُودُهُم﴾ .\n\n#### لام (هل) و(بل)\n\n تقع لام (هل وبل) قبل ثمانية أحرف (مجموعة في بيت الشاطبية: بَلْ وَهَلْ رَوَوْا...).\n\n **مذهب ورش:**\n أظهر ورش لام (هل) و(بل) عند جميع الحروف ما عدا اللام والراء للتماثل والتقارب العام لكل القراء (مثل: بَل رَّان، بَل لَّا يَخَافُون). وأدغم لام (هل) في التاء في قوله تعالى: ﴿فَهَل تَّرَى لَهُم مِّن بَاقِيَةٍ﴾ وغيرها.\n\n#### تنبيه في حروف قربت مخارجها\n\n ورش يدغم الثاء في التاء في (أورثتموها، لبثت، لبثتم). ويدغم الذال في التاء في (أخذت، اتخذتم).",
  "u6-l2": "## \n \n تاء التأنيث ولام (هل) و(بل)\n\n#### تاء التأنيث الساكنة\n\n تأتي تاء التأنيث قبل ستة أحرف: السين، الثاء، الصاد، الزاي، الطاء، الجيم.\n\n **مذهب ورش:**\n أدغم ورش تاء التأنيث في الظاء فقط في قوله تعالى: ﴿كَانَت ظَّالِمَةً﴾ . وأظهرها عند باقي الحروف، مثل: ﴿حَصِرَتْ صُدُورُهُم﴾ ، ﴿نَضَجَتْ جُلُودُهُم﴾ .\n\n#### لام (هل) و(بل)\n\n تقع لام (هل وبل) قبل ثمانية أحرف (مجموعة في بيت الشاطبية: بَلْ وَهَلْ رَوَوْا...).\n\n **مذهب ورش:**\n أظهر ورش لام (هل) و(بل) عند جميع الحروف ما عدا اللام والراء للتماثل والتقارب العام لكل القراء (مثل: بَل رَّان، بَل لَّا يَخَافُون). وأدغم لام (هل) في التاء في قوله تعالى: ﴿فَهَل تَّرَى لَهُم مِّن بَاقِيَةٍ﴾ وغيرها.\n\n#### تنبيه في حروف قربت مخارجها\n\n ورش يدغم الثاء في التاء في (أورثتموها، لبثت، لبثتم). ويدغم الذال في التاء في (أخذت، اتخذتم).",
  "warsh-unit-7-u7-l1": "## \n \n الوقف على هاء التأنيث\n\n### \n \n الشاهد من الشاطبية\n\n وَإِنْ كُتِبَتْ تَاءً فَبِالْهَاءِ وُقْفُهَا ... نَدًا ضَافَ وَالْبَاقُونَ بِالتَّاءِ أَنْزَلاَ\n\n **الشرح:** الكلمات المنتهية بتاء التأنيث المفتوحة في المصحف (مثل: رحْمَت، نِعْمَت، شَجَرَت). وقف عليها بعض القراء بالهاء وبعضهم بالتاء المفتوحة.\n\n#### مذهب ورش في الوقف\n\n ورش يقف على تاء التأنيث المفتوحة المكتوبة في المصحف (تاءً مجرورة) بـ **التاء** كما رُسمت.\n\n* ﴿رَحْمَت﴾ يقف عليها: رَحْمَتْ\n \n* ﴿نِعْمَت﴾ يقف عليها: نِعْمَتْ\n \n* ﴿سُنَّت﴾ يقف عليها: سُنَّتْ\n\n وذلك اتباعاً لرسم المصحف، وهو الأصل عند معظم القراء سوى من ذُكروا في البيت (ابن كثير، والكسائي، وأبو عمرو).",
  "u7-l1": "## \n \n الوقف على هاء التأنيث\n\n### \n \n الشاهد من الشاطبية\n\n وَإِنْ كُتِبَتْ تَاءً فَبِالْهَاءِ وُقْفُهَا ... نَدًا ضَافَ وَالْبَاقُونَ بِالتَّاءِ أَنْزَلاَ\n\n **الشرح:** الكلمات المنتهية بتاء التأنيث المفتوحة في المصحف (مثل: رحْمَت، نِعْمَت، شَجَرَت). وقف عليها بعض القراء بالهاء وبعضهم بالتاء المفتوحة.\n\n#### مذهب ورش في الوقف\n\n ورش يقف على تاء التأنيث المفتوحة المكتوبة في المصحف (تاءً مجرورة) بـ **التاء** كما رُسمت.\n\n* ﴿رَحْمَت﴾ يقف عليها: رَحْمَتْ\n \n* ﴿نِعْمَت﴾ يقف عليها: نِعْمَتْ\n \n* ﴿سُنَّت﴾ يقف عليها: سُنَّتْ\n\n وذلك اتباعاً لرسم المصحف، وهو الأصل عند معظم القراء سوى من ذُكروا في البيت (ابن كثير، والكسائي، وأبو عمرو).",
  "warsh-unit-7-u7-l2": "## \n \n المقطوع والموصول\n\n من أصول القراءة معرفة المقطوع والموصول في رسم المصحف العثماني للوقف عليها الاضطراري أو الاختباري.\n\n#### قاعدة الوقف لورش وللجمهور\n\n يجب الوقف على الكلمات حسب رسمها في المصحف الإمام:\n\n* \n \n **المقطوع**\n يجوز الوقف على الكلمة الأولى منهما (اختباراً أو اضطراراً). \n \n مثل: أَن لَّن (يقف على أن) \n\n* \n \n **الموصول**\n لا يجوز الوقف إلا على الكلمة الثانية لأنهما رُسمتا كلمة واحدة. \n \n مثل: أَلَّن (يقف على ألَّن) \n\n يعد الوقف على المقطوع والموصول من باب الوقف الاختباري (للاختبار) أو الاضطراري (لانقطاع النفس)، ولا يُتعمد الوقف عليه في القراءة العادية. وورش يوافق الجمهور في اتباع الرسم العثماني.",
  "u7-l2": "## \n \n المقطوع والموصول\n\n من أصول القراءة معرفة المقطوع والموصول في رسم المصحف العثماني للوقف عليها الاضطراري أو الاختباري.\n\n#### قاعدة الوقف لورش وللجمهور\n\n يجب الوقف على الكلمات حسب رسمها في المصحف الإمام:\n\n* \n \n **المقطوع**\n يجوز الوقف على الكلمة الأولى منهما (اختباراً أو اضطراراً). \n \n مثل: أَن لَّن (يقف على أن) \n\n* \n \n **الموصول**\n لا يجوز الوقف إلا على الكلمة الثانية لأنهما رُسمتا كلمة واحدة. \n \n مثل: أَلَّن (يقف على ألَّن) \n\n يعد الوقف على المقطوع والموصول من باب الوقف الاختباري (للاختبار) أو الاضطراري (لانقطاع النفس)، ولا يُتعمد الوقف عليه في القراءة العادية. وورش يوافق الجمهور في اتباع الرسم العثماني.",
  "warsh-unit-8-u8-l1": "## \n \n ذوات الياء\n\n### \n \n الشاهد من الشاطبية (بشرح الوسيط)\n\n وَذُو الرَّاءِ وَرْشٌ بَيْنَ بَيْنَ وَفِي أَرَا ... كَهُمْ وَذَوَاتِ الْيَا لَهُ الْخُلْفُ جُمِّلاَ\n\n **شرح ما بين السطور:** التقليل (أو الإمالة الصغرى، أو بين بين) هو النطق بالألف بين الفتح والإمالة الكبرى. يذكر الإمام الشاطبي أن ورشاً يقلل ذوات الراء قولاً واحداً، أما \"ذوات الياء\" ففيها الخُلف (الوجهان: الفتح والتقليل).\n\n#### ما هي ذوات الياء؟\n\nهي كل ألف متطرفة أصلية منقلبة عن ياء، أو رُسمت في المصحف ياءً (غير ذوات الراء). مثل:\n\n* الْهُدَى\n \n* مُوسَى\n \n* يَحْيَى\n \n* سَعَى\n\nكيف نعرف أصل الألف؟\n\n* في الأسماء: بالتثنية (فتى &larr; فتيان) إذن هي منقلبة عن ياء.\n \n* في الأفعال: بإسناد الفعل لنفسك (سعى &larr; سعيتُ) إذن هي منقلبة عن ياء.\n\n#### أوجه ورش في ذوات الياء (غير الراء)\n\nلورش فيها وجهان: **الفتح** و**التقليل**.\n\n **ارتباطها بمد البدل:**\n\nكما علمنا من باب المد، هناك ارتباط بين البدل وذوات الياء عند ورش:\n\n* إذا قصرت البدل (2) &larr; لك في ذات الياء (الفتح).\n \n* إذا توسطت البدل (4) &larr; لك في ذات الياء (التقليل).\n \n* إذا أشبعت البدل (6) &larr; لك في ذات الياء (الفتح والتقليل).",
  "u8-l1": "## \n \n ذوات الياء\n\n### \n \n الشاهد من الشاطبية (بشرح الوسيط)\n\n وَذُو الرَّاءِ وَرْشٌ بَيْنَ بَيْنَ وَفِي أَرَا ... كَهُمْ وَذَوَاتِ الْيَا لَهُ الْخُلْفُ جُمِّلاَ\n\n **شرح ما بين السطور:** التقليل (أو الإمالة الصغرى، أو بين بين) هو النطق بالألف بين الفتح والإمالة الكبرى. يذكر الإمام الشاطبي أن ورشاً يقلل ذوات الراء قولاً واحداً، أما \"ذوات الياء\" ففيها الخُلف (الوجهان: الفتح والتقليل).\n\n#### ما هي ذوات الياء؟\n\nهي كل ألف متطرفة أصلية منقلبة عن ياء، أو رُسمت في المصحف ياءً (غير ذوات الراء). مثل:\n\n* الْهُدَى\n \n* مُوسَى\n \n* يَحْيَى\n \n* سَعَى\n\nكيف نعرف أصل الألف؟\n\n* في الأسماء: بالتثنية (فتى &larr; فتيان) إذن هي منقلبة عن ياء.\n \n* في الأفعال: بإسناد الفعل لنفسك (سعى &larr; سعيتُ) إذن هي منقلبة عن ياء.\n\n#### أوجه ورش في ذوات الياء (غير الراء)\n\nلورش فيها وجهان: **الفتح** و**التقليل**.\n\n **ارتباطها بمد البدل:**\n\nكما علمنا من باب المد، هناك ارتباط بين البدل وذوات الياء عند ورش:\n\n* إذا قصرت البدل (2) &larr; لك في ذات الياء (الفتح).\n \n* إذا توسطت البدل (4) &larr; لك في ذات الياء (التقليل).\n \n* إذا أشبعت البدل (6) &larr; لك في ذات الياء (الفتح والتقليل).",
  "warsh-unit-8-u8-l2": "## \n \n ذوات الراء\n\n### \n \n الشاهد من الشاطبية (بشرح الوسيط)\n\n وَذُو الرَّاءِ وَرْشٌ بَيْنَ بَيْنَ...\n\n **شرح ما بين السطور:** ذوات الراء هي كل ألف متطرفة منقلبة عن ياء وسبقها حرف الراء. حكمها عند ورش: التقليل قولاً واحداً (وجهاً واحداً).\n\n#### أمثلة لذوات الراء\n\n* ﴿ النَّصَارَى ﴾\n \n* ﴿ أَسْكَارَى ﴾\n \n* ﴿ اشْتَرَى ﴾\n \n* ﴿ تَرَى ﴾\n\n#### حكمها\n\n **التقليل قولاً واحداً**\n بخلاف ذوات الياء (غير الراء) التي فيها الوجهان. ذوات الراء ليس لورش فيها إلا التقليل فقط، سواء قرأت بقصر البدل أو توسطه أو مده.",
  "u8-l2": "## \n \n ذوات الراء\n\n### \n \n الشاهد من الشاطبية (بشرح الوسيط)\n\n وَذُو الرَّاءِ وَرْشٌ بَيْنَ بَيْنَ...\n\n **شرح ما بين السطور:** ذوات الراء هي كل ألف متطرفة منقلبة عن ياء وسبقها حرف الراء. حكمها عند ورش: التقليل قولاً واحداً (وجهاً واحداً).\n\n#### أمثلة لذوات الراء\n\n* ﴿ النَّصَارَى ﴾\n \n* ﴿ أَسْكَارَى ﴾\n \n* ﴿ اشْتَرَى ﴾\n \n* ﴿ تَرَى ﴾\n\n#### حكمها\n\n **التقليل قولاً واحداً**\n بخلاف ذوات الياء (غير الراء) التي فيها الوجهان. ذوات الراء ليس لورش فيها إلا التقليل فقط، سواء قرأت بقصر البدل أو توسطه أو مده.",
  "warsh-unit-8-u8-l3": "## \n \n رؤوس الآي ومستثنيات الباب\n\n### رؤوس الآي في السور الإحدى عشرة\n\n رؤوس الآي هي الكلمات التي تنتهي بها الآيات. لورش في رؤوس الآي لـ 11 سورة حكم خاص وهو **التقليل قولاً واحداً** (إذا لم تكن منتهية بهاء التأنيث).\n\nوالسور هي:\n\n (طه، النجم، المعارج، القيامة، النازعات، عبس، الأعلى، الشمس، الليل، الضحى، العلق).\n\n **مثال:** ﴿ وَالضُّحَى ۝ وَاللَّيْلِ إِذَا سَجَى ﴾ تقلل قولاً واحداً.\n \n **استثناء:** إذا اتصلت بها (ها) التأنيث مثل ﴿ وَالشَّمْسِ وَضُحَاهَا ﴾ فتعود للقاعدة الأصلية (ذوات الياء) وفيها الوجهان (الفتح والتقليل).",
  "u8-l3": "## \n \n رؤوس الآي ومستثنيات الباب\n\n### رؤوس الآي في السور الإحدى عشرة\n\n رؤوس الآي هي الكلمات التي تنتهي بها الآيات. لورش في رؤوس الآي لـ 11 سورة حكم خاص وهو **التقليل قولاً واحداً** (إذا لم تكن منتهية بهاء التأنيث).\n\nوالسور هي:\n\n (طه، النجم، المعارج، القيامة، النازعات، عبس، الأعلى، الشمس، الليل، الضحى، العلق).\n\n **مثال:** ﴿ وَالضُّحَى ۝ وَاللَّيْلِ إِذَا سَجَى ﴾ تقلل قولاً واحداً.\n \n **استثناء:** إذا اتصلت بها (ها) التأنيث مثل ﴿ وَالشَّمْسِ وَضُحَاهَا ﴾ فتعود للقاعدة الأصلية (ذوات الياء) وفيها الوجهان (الفتح والتقليل).",
  "warsh-unit-9-u9-l1": "## \n \n شروط ترقيق الراء\n\n### \n \n الشاهد من الشاطبية (بشرح الوسيط)\n\n وَرَقَّقَ وَرْشٌ كُلَّ رَاءٍ وَقَبْلَهَا ... مُسَكَّنَةً يَاءٌ أَوِ الْكَسْرُ مُوصَلاَ \n وَلَمْ يَرَ فَصْلاً سَاكِناً بَعْدَ كَسْرَةٍ ... سِوَى حَرْفِ الاِسْتِعْلاَ سِوَى الْخَا فَكَمَّلاَ\n\n **شرح ما بين السطور:** الراء في الأصل مفخمة إذا كانت مفتوحة أو مضمومة. ولكن ورشاً يرققها بشروط محددة ذكرها الإمام الشاطبي، ووضحها د. صبري سلامة في الوسيط، وهي تدور حول تأثير الكسرة أو الياء على الراء.\n\n#### شروط الترقيق\n\nترقق الراء المفتوحة أو المضمومة لورش إذا توفر فيها أحد الأسباب التالية:\n\n* \n **1. أن يسبقها كسر أصلي متصل بها**\n\nيجب أن تكون الكسرة في نفس الكلمة وأصلية.\n\n أمثلة: ﴿سِرَاجاً﴾ ، ﴿الآخِرَة﴾ ، ﴿فِرَاشاً﴾ \n\n* \n **2. أن يسبقها ياء ساكنة**\n\nسواء كانت الياء للين أو للمد.\n\n أمثلة: ﴿خَيْر﴾ ، ﴿بَصِير﴾ ، ﴿الطَّيْر﴾ \n\n* \n **3. أن يفصل بينها وبين الكسر الساكن غير حرف استعلاء**\n\nيجوز الفصل بحرف ساكن مستفل (مرقق)، ويُستثنى من حروف الاستعلاء حرف (الخاء) فإنه لا يمنع الترقيق.\n\n أمثلة: ﴿إِكْرَاه﴾ ، ﴿إِخْرَاج﴾ (الخاء مستعلية ولكنها مستثناة).",
  "u9-l1": "## \n \n شروط ترقيق الراء\n\n### \n \n الشاهد من الشاطبية (بشرح الوسيط)\n\n وَرَقَّقَ وَرْشٌ كُلَّ رَاءٍ وَقَبْلَهَا ... مُسَكَّنَةً يَاءٌ أَوِ الْكَسْرُ مُوصَلاَ \n وَلَمْ يَرَ فَصْلاً سَاكِناً بَعْدَ كَسْرَةٍ ... سِوَى حَرْفِ الاِسْتِعْلاَ سِوَى الْخَا فَكَمَّلاَ\n\n **شرح ما بين السطور:** الراء في الأصل مفخمة إذا كانت مفتوحة أو مضمومة. ولكن ورشاً يرققها بشروط محددة ذكرها الإمام الشاطبي، ووضحها د. صبري سلامة في الوسيط، وهي تدور حول تأثير الكسرة أو الياء على الراء.\n\n#### شروط الترقيق\n\nترقق الراء المفتوحة أو المضمومة لورش إذا توفر فيها أحد الأسباب التالية:\n\n* \n **1. أن يسبقها كسر أصلي متصل بها**\n\nيجب أن تكون الكسرة في نفس الكلمة وأصلية.\n\n أمثلة: ﴿سِرَاجاً﴾ ، ﴿الآخِرَة﴾ ، ﴿فِرَاشاً﴾ \n\n* \n **2. أن يسبقها ياء ساكنة**\n\nسواء كانت الياء للين أو للمد.\n\n أمثلة: ﴿خَيْر﴾ ، ﴿بَصِير﴾ ، ﴿الطَّيْر﴾ \n\n* \n **3. أن يفصل بينها وبين الكسر الساكن غير حرف استعلاء**\n\nيجوز الفصل بحرف ساكن مستفل (مرقق)، ويُستثنى من حروف الاستعلاء حرف (الخاء) فإنه لا يمنع الترقيق.\n\n أمثلة: ﴿إِكْرَاه﴾ ، ﴿إِخْرَاج﴾ (الخاء مستعلية ولكنها مستثناة).",
  "warsh-unit-9-u9-l2": "## \n \n ما يفخم من الراءات استثناءً\n\n هناك راءات توافرت فيها شروط الترقيق، لكن الإمام ورشاً استثناها ففخمها.\n\n#### 1. الأسماء الأعجمية\n\nمثل: ﴿إِبْرَاهِيم﴾، ﴿إِسْرَائِيل﴾، ﴿عِمْرَان﴾ \n\nالسبب: لأن العجمة تمنع الترقيق كما تمنع الصرف.\n\n#### 2. الراء المكررة (التي بعدها راء)\n\nمثل: ﴿ضِرَاراً﴾، ﴿فِرَاراً﴾، ﴿إِسْرَاراً﴾ \n\nالسبب: لثقل تكرار الراء، ففخمت لتناسب أختها.\n\n#### 3. وزن (فِعْلاً) المستثنى\n\nذكرت الشاطبية كلمات مخصوصة: ﴿إِرَماً﴾ وكلمات وزن (فِعلاً) وهي: ﴿سِتْراً﴾، ﴿وِزْراً﴾، ﴿إِصْراً﴾، ﴿ذِكْراً﴾، ﴿صِهْراً﴾، ﴿حِجْراً﴾ \n\nكلها مفخمة قولاً واحداً (وفي ذكرى الوجهان لأنها ذات ياء).",
  "u9-l2": "## \n \n ما يفخم من الراءات استثناءً\n\n هناك راءات توافرت فيها شروط الترقيق، لكن الإمام ورشاً استثناها ففخمها.\n\n#### 1. الأسماء الأعجمية\n\nمثل: ﴿إِبْرَاهِيم﴾، ﴿إِسْرَائِيل﴾، ﴿عِمْرَان﴾ \n\nالسبب: لأن العجمة تمنع الترقيق كما تمنع الصرف.\n\n#### 2. الراء المكررة (التي بعدها راء)\n\nمثل: ﴿ضِرَاراً﴾، ﴿فِرَاراً﴾، ﴿إِسْرَاراً﴾ \n\nالسبب: لثقل تكرار الراء، ففخمت لتناسب أختها.\n\n#### 3. وزن (فِعْلاً) المستثنى\n\nذكرت الشاطبية كلمات مخصوصة: ﴿إِرَماً﴾ وكلمات وزن (فِعلاً) وهي: ﴿سِتْراً﴾، ﴿وِزْراً﴾، ﴿إِصْراً﴾، ﴿ذِكْراً﴾، ﴿صِهْراً﴾، ﴿حِجْراً﴾ \n\nكلها مفخمة قولاً واحداً (وفي ذكرى الوجهان لأنها ذات ياء).",
  "warsh-unit-10-u10-l1": "## \n \n شروط تغليظ اللام لورش\n\n### \n \n الشاهد من الشاطبية\n\n وَغَلَّظَ وَرْشٌ فَتْحَ لاَمٍ لِصَادِهَا ... أَوِ الطَّاءِ أَوْ لِلظَّاءِ قَبْلُ تَنَزَّلاَ \n إِذَا فُتِحَتْ أَوْ سُكِّنَتْ كَصَلاَتِهِمْ ... وَمَطْلَعِ أَيْضاً ثُمَّ ظَلَّ وَيُوصَلاَ\n\n **الشرح:** اختص ورش (من طريق الأزرق) بتغليظ اللام إذا توفرت فيها شروط مجتمعة تتعلق بحركتها وحركة الحرف الذي قبلها ونوع ذلك الحرف.\n\n#### شروط التغليظ الثلاثة\n\n* **أن تكون اللام مفتوحة:** (سواء خفيفة أو مشددة).\n \n* **أن يسبقها أحد ثلاثة أحرف:** (الصاد، الطاء، الظاء).\n \n* **أن يكون هذا الحرف السابق:** مفتوحاً أو ساكناً.\n\n بعد الصاد \n ﴿الصَّلَاةَ ، يَصْلَىٰ﴾ \n\n بعد الطاء \n ﴿الطَّلَاقُ ، مَطْلَعِ﴾ \n\n بعد الظاء \n ﴿ظَلَمَ ، أَظْلَمَ﴾",
  "u10-l1": "## \n \n شروط تغليظ اللام لورش\n\n### \n \n الشاهد من الشاطبية\n\n وَغَلَّظَ وَرْشٌ فَتْحَ لاَمٍ لِصَادِهَا ... أَوِ الطَّاءِ أَوْ لِلظَّاءِ قَبْلُ تَنَزَّلاَ \n إِذَا فُتِحَتْ أَوْ سُكِّنَتْ كَصَلاَتِهِمْ ... وَمَطْلَعِ أَيْضاً ثُمَّ ظَلَّ وَيُوصَلاَ\n\n **الشرح:** اختص ورش (من طريق الأزرق) بتغليظ اللام إذا توفرت فيها شروط مجتمعة تتعلق بحركتها وحركة الحرف الذي قبلها ونوع ذلك الحرف.\n\n#### شروط التغليظ الثلاثة\n\n* **أن تكون اللام مفتوحة:** (سواء خفيفة أو مشددة).\n \n* **أن يسبقها أحد ثلاثة أحرف:** (الصاد، الطاء، الظاء).\n \n* **أن يكون هذا الحرف السابق:** مفتوحاً أو ساكناً.\n\n بعد الصاد \n ﴿الصَّلَاةَ ، يَصْلَىٰ﴾ \n\n بعد الطاء \n ﴿الطَّلَاقُ ، مَطْلَعِ﴾ \n\n بعد الظاء \n ﴿ظَلَمَ ، أَظْلَمَ﴾",
  "warsh-unit-10-u10-l2": "## \n \n اللام التي فيها الوجهان\n\n هناك حالات توافرت فيها الشروط ولكن طرأ عليها ما يضعف سبب التغليظ، فيجوز لورش فيها التغليظ (والتغليظ هو المقدم) والترقيق.\n\n#### 1. إذا حيل بين اللام والحرف بالألف\n\nوقع ذلك في ثلاث كلمات في القرآن:\n\n* طَالَ\n \n* فِصَالاً\n \n* يَصَّالَحَا (صَالَحَا)\n\nالتغليظ أقوى وأولى.\n\n#### 2. إذا كانت اللام متطرفة ووُقف عليها\n\nبالسكون العارض:\n\n* بَطَلَ\n \n* فَصَلَ\n \n* يُوصَلَ\n\nعند الوقف فيها الوجهان (التغليظ والترقيق)، وعند الوصل تغلظ قولاً واحداً.\n\n#### 3. ذوات الياء (التقاء البابين)\n\nإذا اجتمع سبب التغليظ مع سبب التقليل في نفس الكلمة (مثل: مُصَلَّى، يَصْلَاهَا).\n\n **إذا قللت الألف (ذات الياء)**\n يجب ترقيق اللام للتناسب. \n\n **إذا فتحت الألف**\n يجب تغليظ اللام.",
  "u10-l2": "## \n \n اللام التي فيها الوجهان\n\n هناك حالات توافرت فيها الشروط ولكن طرأ عليها ما يضعف سبب التغليظ، فيجوز لورش فيها التغليظ (والتغليظ هو المقدم) والترقيق.\n\n#### 1. إذا حيل بين اللام والحرف بالألف\n\nوقع ذلك في ثلاث كلمات في القرآن:\n\n* طَالَ\n \n* فِصَالاً\n \n* يَصَّالَحَا (صَالَحَا)\n\nالتغليظ أقوى وأولى.\n\n#### 2. إذا كانت اللام متطرفة ووُقف عليها\n\nبالسكون العارض:\n\n* بَطَلَ\n \n* فَصَلَ\n \n* يُوصَلَ\n\nعند الوقف فيها الوجهان (التغليظ والترقيق)، وعند الوصل تغلظ قولاً واحداً.\n\n#### 3. ذوات الياء (التقاء البابين)\n\nإذا اجتمع سبب التغليظ مع سبب التقليل في نفس الكلمة (مثل: مُصَلَّى، يَصْلَاهَا).\n\n **إذا قللت الألف (ذات الياء)**\n يجب ترقيق اللام للتناسب. \n\n **إذا فتحت الألف**\n يجب تغليظ اللام.",
  "warsh-unit-11-u11-l1": "## \n \n أحوال صلة هاء الكناية\n\n### \n \n الشاهد من الشاطبية\n\n وَلَمْ يَصِلُوا هَاءَ مُضْمَرٍ قَبْلَ سَاكِنٍ ... وَمَا قَبْلَهُ التَّحْرِيكُ لِلْكُلِّ وُصِّلاَ \n وَمَا قَبْلَهُ التَّسْكِينُ لِابْنِ كَثِيرِهِمْ ...\n\n#### القاعدة العامة لورش\n\nهاء الكناية (هاء الضمير المفرد المذكر الغائب)، لها أحوال:\n\n* \n **1. أن تقع بين متحركين**\n\nيصلها ورش (والقراء جميعاً) بواو إن كانت مضمومة، وبياء إن كانت مكسورة.\n\n ﴿إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًا﴾ \n\n* \n **2. أن تقع قبل ساكن (سواء ما قبلها متحرك أو ساكن)**\n\nلا يصلها ورش ولا أحد من القراء.\n\n ﴿لَهُ الْمُلْكُ﴾ ، ﴿عَلَيْهِ اللَّهُ﴾ \n\n* \n **3. أن تقع بعد ساكن وقبل متحرك**\n\nلا يصلها ورش (ويصلها ابن كثير فقط).\n\n ﴿فِيهِ هُدًى﴾ يقرؤها ورش بكسر الهاء بدون صلة (ياء).",
  "u11-l1": "## \n \n أحوال صلة هاء الكناية\n\n### \n \n الشاهد من الشاطبية\n\n وَلَمْ يَصِلُوا هَاءَ مُضْمَرٍ قَبْلَ سَاكِنٍ ... وَمَا قَبْلَهُ التَّحْرِيكُ لِلْكُلِّ وُصِّلاَ \n وَمَا قَبْلَهُ التَّسْكِينُ لِابْنِ كَثِيرِهِمْ ...\n\n#### القاعدة العامة لورش\n\nهاء الكناية (هاء الضمير المفرد المذكر الغائب)، لها أحوال:\n\n* \n **1. أن تقع بين متحركين**\n\nيصلها ورش (والقراء جميعاً) بواو إن كانت مضمومة، وبياء إن كانت مكسورة.\n\n ﴿إِنَّهُۥ كَانَ بِعِبَادِهِۦ خَبِيرًا﴾ \n\n* \n **2. أن تقع قبل ساكن (سواء ما قبلها متحرك أو ساكن)**\n\nلا يصلها ورش ولا أحد من القراء.\n\n ﴿لَهُ الْمُلْكُ﴾ ، ﴿عَلَيْهِ اللَّهُ﴾ \n\n* \n **3. أن تقع بعد ساكن وقبل متحرك**\n\nلا يصلها ورش (ويصلها ابن كثير فقط).\n\n ﴿فِيهِ هُدًى﴾ يقرؤها ورش بكسر الهاء بدون صلة (ياء).",
  "warsh-unit-11-u11-l2": "## \n \n الاستثناءات والكلمات المخصوصة\n\n هناك كلمات خرجت عن القاعدة الأصلية ونصّ عليها الأئمة في القراءة لورش.\n\n#### ﴿يَرْضَهُ لَكُمْ﴾\n\nقرأها ورش بضم الهاء من غير صلة (مع أنها بين متحركين). (الشاهد: وفي يرضه يمناً...)\n\n#### ﴿يَتَّقْهِ﴾\n\nفي سورة النور (ويتقهْ فأولئك). قرأها ورش بكسر القاف وكسر الهاء مع الصلة (يَتَّقِهِۦ).\n\n#### ﴿يَأْتِهِ﴾\n\nفي سورة طه (ومن يأته مؤمناً). قرأها ورش بكسر الهاء وقصرها (من غير صلة).\n\n#### ﴿أَرْجِهْ﴾\n\nفي الأعراف والشعراء. قرأها ورش بزيادة همزة ساكنة وضم الهاء مع الصلة (أَرْجِئْهُۥ).\n\n#### ﴿فَأَلْقِهْ﴾\n\nفي سورة النمل (فألقه إليهم). قرأها ورش بكسر الهاء مع الصلة (فَأَلْقِهِۦٓ إِلَيْهِمْ)، وتمد إشباعاً لأن بعدها همزة قطع.",
  "u11-l2": "## \n \n الاستثناءات والكلمات المخصوصة\n\n هناك كلمات خرجت عن القاعدة الأصلية ونصّ عليها الأئمة في القراءة لورش.\n\n#### ﴿يَرْضَهُ لَكُمْ﴾\n\nقرأها ورش بضم الهاء من غير صلة (مع أنها بين متحركين). (الشاهد: وفي يرضه يمناً...)\n\n#### ﴿يَتَّقْهِ﴾\n\nفي سورة النور (ويتقهْ فأولئك). قرأها ورش بكسر القاف وكسر الهاء مع الصلة (يَتَّقِهِۦ).\n\n#### ﴿يَأْتِهِ﴾\n\nفي سورة طه (ومن يأته مؤمناً). قرأها ورش بكسر الهاء وقصرها (من غير صلة).\n\n#### ﴿أَرْجِهْ﴾\n\nفي الأعراف والشعراء. قرأها ورش بزيادة همزة ساكنة وضم الهاء مع الصلة (أَرْجِئْهُۥ).\n\n#### ﴿فَأَلْقِهْ﴾\n\nفي سورة النمل (فألقه إليهم). قرأها ورش بكسر الهاء مع الصلة (فَأَلْقِهِۦٓ إِلَيْهِمْ)، وتمد إشباعاً لأن بعدها همزة قطع.",
  "warsh-unit-12-u12-l1": "## \n \n صلة ميم الجمع عند ورش\n\n### \n \n الشاهد من الشاطبية\n\n وَمِنْ قَبْلِ هَمْزِ الْقَطْعِ صِلْهَا لِوَرْشِهِمْ ... وَأَسْكَنَهَا الْبَاقُونَ بَعْدُ لِتَكْمُلاَ\n\n#### الحكم العام\n\n ميم الجمع هي الميم الزائدة الدالة على جمع المذكر السالم (مثل: عليهم، أنتم، لكم). ولها أحكام عند القراء إذا وقعت قبل حرف متحرك.\n\n **مذهب ورش:** يصل ميم الجمع بواو لفظية وتمد ست حركات (إشباعاً) **فقط** إذا جاء بعدها **همزة قطع متحركة**.\n\n* ﴿عَلَيْهِمْ ءَأَنذَرْتَهُمْ﴾ تُقرأ: عَلَيْهِمُوٓ ءَأَنذَرْتَهُمْ (بالصلة والإشباع).\n \n* ﴿لَكُمْ أَنفُسَكُمْ﴾ تُقرأ: لَكُمُوٓ أَنفُسَكُمْ.\n\n أما إذا جاء بعد ميم الجمع أي حرف آخر غير همزة القطع (مثل: عليهم غير)، فإن ورشاً يسكن الميم كحفص والجمهور.",
  "u12-l1": "## \n \n صلة ميم الجمع عند ورش\n\n### \n \n الشاهد من الشاطبية\n\n وَمِنْ قَبْلِ هَمْزِ الْقَطْعِ صِلْهَا لِوَرْشِهِمْ ... وَأَسْكَنَهَا الْبَاقُونَ بَعْدُ لِتَكْمُلاَ\n\n#### الحكم العام\n\n ميم الجمع هي الميم الزائدة الدالة على جمع المذكر السالم (مثل: عليهم، أنتم، لكم). ولها أحكام عند القراء إذا وقعت قبل حرف متحرك.\n\n **مذهب ورش:** يصل ميم الجمع بواو لفظية وتمد ست حركات (إشباعاً) **فقط** إذا جاء بعدها **همزة قطع متحركة**.\n\n* ﴿عَلَيْهِمْ ءَأَنذَرْتَهُمْ﴾ تُقرأ: عَلَيْهِمُوٓ ءَأَنذَرْتَهُمْ (بالصلة والإشباع).\n \n* ﴿لَكُمْ أَنفُسَكُمْ﴾ تُقرأ: لَكُمُوٓ أَنفُسَكُمْ.\n\n أما إذا جاء بعد ميم الجمع أي حرف آخر غير همزة القطع (مثل: عليهم غير)، فإن ورشاً يسكن الميم كحفص والجمهور.",
  "warsh-unit-12-u12-l2": "## \n \n ميم الجمع عند التقاء الساكنين\n\n#### الحكم إذا جاء بعد الميم همزة وصل\n\n إذا وقع بعد ميم الجمع ساكن (كهمزة الوصل في \"ال\" التعريف)، فما هو العمل للتخلص من التقاء الساكنين؟\n\n **القاعدة:**\n\n يضم ورش (والقراء جميعاً) ميم الجمع للتخلص من التقاء الساكنين دون صلة.\n\n ﴿عَلَيْهِمُ الذِّلَّةُ﴾ ، ﴿مِنكُمُ الرِّجَالُ﴾ ، ﴿بِهِمُ الأَسْبَابُ﴾\n\n**ملاحظة هامة:**\n\nإذا كانت الميم قبل همزة وصل وكان الحرف الذي قبل الميم هاء مكسورة، مثل: ﴿فِي قُلُوبِهِمُ الْمَرَضُ﴾، فإن ورشاً يقرؤها بضم الميم وكسر الهاء (قُلُوبِهِمُ الْمَرَضُ)، خلافاً لأبي عمرو الذي يكسر الميم أيضاً (قُلُوبِهِمِ الْمَرَضُ).",
  "u12-l2": "## \n \n ميم الجمع عند التقاء الساكنين\n\n#### الحكم إذا جاء بعد الميم همزة وصل\n\n إذا وقع بعد ميم الجمع ساكن (كهمزة الوصل في \"ال\" التعريف)، فما هو العمل للتخلص من التقاء الساكنين؟\n\n **القاعدة:**\n\n يضم ورش (والقراء جميعاً) ميم الجمع للتخلص من التقاء الساكنين دون صلة.\n\n ﴿عَلَيْهِمُ الذِّلَّةُ﴾ ، ﴿مِنكُمُ الرِّجَالُ﴾ ، ﴿بِهِمُ الأَسْبَابُ﴾\n\n**ملاحظة هامة:**\n\nإذا كانت الميم قبل همزة وصل وكان الحرف الذي قبل الميم هاء مكسورة، مثل: ﴿فِي قُلُوبِهِمُ الْمَرَضُ﴾، فإن ورشاً يقرؤها بضم الميم وكسر الهاء (قُلُوبِهِمُ الْمَرَضُ)، خلافاً لأبي عمرو الذي يكسر الميم أيضاً (قُلُوبِهِمِ الْمَرَضُ).",
  "warsh-unit-13-waqf-tool": "## الوقف والابتداء\n\n باب الوقف والابتداء من أهم أبواب التجويد، وقد روي عن الإمام علي بن أبي طالب رضي الله عنه في قوله تعالى: (وَرَتِّلِ الْقُرْآنَ تَرْتِيلًا) أنه قال: الترتيل هو تجويد الحروف ومعرفة الوقوف.\n استخدم الأداة التفاعلية أدناه للتدرب على أحكام الوقف والابتداء في قراءة ورش.",
  "waqf-tool": "## الوقف والابتداء\n\n باب الوقف والابتداء من أهم أبواب التجويد، وقد روي عن الإمام علي بن أبي طالب رضي الله عنه في قوله تعالى: (وَرَتِّلِ الْقُرْآنَ تَرْتِيلًا) أنه قال: الترتيل هو تجويد الحروف ومعرفة الوقوف.\n استخدم الأداة التفاعلية أدناه للتدرب على أحكام الوقف والابتداء في قراءة ورش.",
  "qalun-unit-0-u0-l1": "## ترجمة الإمام نافع وراويه قالون\n\n### الإمام نافع المدني\n\n هو أبو رويم نافع بن عبد الرحمن بن أبي نعيم الليثي، إمام أهل المدينة في القراءة. أخذ القراءة عن سبعين من التابعين، منهم أبو جعفر يزيد بن القعقاع.\n انتهت إليه رئاسة الإقراء بالمدينة، وكان يقرئ الناس في مسجد رسول الله صلى الله عليه وسلم أكثر من سبعين سنة.\n\n### الراوي: قالون\n\n هو أبو موسى عيسى بن مينا بن وردان بن عيسى الزرقي مولى بني زهرة.\n\n* **لقبه:** لَقَّبه شيخه نافع بـ (قالون) لجودة قراءته، فإن (قالون) باللغة الرومية تعني: جيد.\n \n* **أخذه للقراءة:** قرأ على نافع سنة خمسين ومائة، وهو ربيب نافع (ابن زوجته)، ولزمه كثيراً حتى قال نافع: \"كم تقرأ علي؟ اجلس إلى أسطوانة حتى أرسل إليك من يقرأ عليك\".\n \n* **لطيفة:** كان قالون أصمَّ لا يسمع البوق، فإذا قُرئ عليه القرآن سمعه!",
  "qalun-unit-0-u0-l2": "## مقدمة في أصول قالون\n\n تتميز قراءة قالون عن نافع بمجموعة من الأصول التي تخالف رواية حفص عن عاصم، وأبرز هذه الأصول التي سندرسها في هذا المسار:\n\n#### 1. البسملة\n\nيثبت البسملة بين السورتين قولاً واحداً (إلا بين الأنفال والتوبة).\n\n#### 2. ميم الجمع\n\nله فيها وجهان: الإسكان (كحفص)، والصلة (ضم الميم ووصلها بواو لفظية).\n\n#### 3. المد والقصر\n\nيقرأ بقصر المنفصل وتوسطه، وتوسط المتصل.\n\n#### 4. هاء الكناية\n\nيسكن الهاء أو يختلس حركتها في كلمات مخصوصة (مثل: يؤده، نوله).\n\n#### 5. الهمزتان من كلمة\n\nيسهل الهمزة الثانية مع إدخال ألف بينهما.\n\n#### 6. الهمزتان من كلمتين\n\nيُسقط الهمزة الأولى إذا اتفقتا، ويسهلها إذا اختلفتا، حسب تفصيل الباب.",
  "qalun-unit-1-u1-l1": "## البسملة بين السورتين\n\n مذهب الإمام قالون في البسملة بين السورتين هو **إثبات البسملة قولاً واحداً** (أي الفصل بالبسملة بين كل سورتين متتاليتين)، وذلك كحفص تماماً.\n\n### بين الأنفال والتوبة\n\nيستثنى من ذلك ما بين سورتي الأنفال والتوبة، فله فيها الأوجه الثلاثة الجائزة لكل القراء:\n\n* **الوقف:** الوقف على آخر الأنفال، والتنفس، ثم الابتداء بأول التوبة.\n \n* **السكت:** السكت على آخر الأنفال سكتة لطيفة بلا تنفس، ثم الابتداء بأول التوبة.\n \n* **الوصل:** وصل آخر الأنفال بأول التوبة.\n\nملاحظة هامة: لا يجوز وصل آخر السورة بالبسملة والوقف عليها، ثم الابتداء بأول السورة التالية، فهذا الوجه ممتنع لجميع القراء.",
  "qalun-unit-1-u1-l2": "## أحكام ميم الجمع\n\n ميم الجمع هي الميم الزائدة الدالة على جمع المذكرين، مثل: (عَلَيْكُمْ)، (أَنْتُمْ).\n\n### مذهبه فيها وجهان:\n\n* \n 1 \n\n#### الإسكان\n\nوهو كقراءة حفص، تقرأ ساكنة (عَلَيْكُمْ أَنفُسَكُمْ).\n\n* \n 2 \n\n#### الصلة\n\nوهو ضم الميم ووصلها بواو لفظية تُمَدُّ بمقدار حركتين (عَلَيْكُمُو أَنفُسَكُمُو).\n\n### إذا وقع بعدها همزة قطع\n\nتمد واو الصلة من باب المد المنفصل:\n\n* فإذا قرأنا بقصر المنفصل، نمد الصلة حركتين (عَلَيْكُمُو أَنفُسَكُمُو).\n \n* وإذا قرأنا بتوسط المنفصل، نمد الصلة أربع حركات (عَلَيْكُمُوو أَنفُسَكُمُو).\n\n **تنبيه:** إذا وقع بعد ميم الجمع حرف ساكن (مثل: عَلَيْكُمُ الصِّيَامُ)، فإنه يضم الميم تخلصاً من التقاء الساكنين، ولا يقرأ بالصلة هنا.",
  "qalun-unit-2-u2-l1": "## الكلمات المخصوصة في هاء الكناية\n\n هاء الكناية هي الهاء الزائدة الدالة على المفرد المذكر الغائب. يقرأ قالون كلمات مخصوصة في القرآن بخلاف أصل القاعدة (إما بالإسكان أو بالاختلاس).\n\n### أولاً: الكلمات التي يقرؤها بالإسكان:\n\n* (يُؤَدِّهْ) موضعي آل عمران.\n \n* (نُوَلِّهْ - وَنُصْلِهْ) في النساء.\n \n* (نُؤْتِهْ) في آل عمران والشورى.\n \n* (فَأَلْقِهْ) في النمل.\n\n### ثانياً: الكلمات التي يقرؤها بالاختلاس (دون إشباع):\n\n* (يَتَّقِهِ) في النور: بكسر القاف واختلاس كسر الهاء (يَتَّقِهِ).\n \n* (يَرْضَهُ) في الزمر: بضم الهاء واختلاس الضمة (يَرْضَهُ).\n \n* (يَأْتِهِ) في طه: باختلاس كسر الهاء (يَأْتِهِ)، وله وجه ثان وهو الإشباع (الصلة).\n\n### ثالثاً: كلمة (يُرْجِئْهُ):\n\nيقرأ قالون كلمة (أَرْجِهْ) في الأعراف والشعراء بزيادة همزة ساكنة وضم الهاء مع صلتها: (أَرْجِئْهُو).",
  "qalun-unit-2-u2-l2": "## المد المتصل والمنفصل\n\n### المد المتصل\n\nهو أن يقع بعد حرف المد همزة في كلمة واحدة، مثل (السَّمَاءِ).\n\nيقرأ قالون بتوسط المتصل (أربع حركات) كحفص.\n\n### المد المنفصل\n\nهو أن يقع حرف المد في آخر الكلمة الأولى والهمزة في أول الكلمة الثانية، مثل (بِمَا أُنزِلَ).\n\nلقالون فيه وجهان:\n\n* القصر (حركتان) - وهو المقدم.\n \n* التوسط (أربع حركات).\n\n### \n 💡 اجتماع المنفصل مع ميم الجمع\n\nفإذا اجتمع المد المنفصل مع ميم الجمع، يتولد لقالون **أربعة أوجه**:\n\n 1. قصر المنفصل + إسكان الميم \n 2. قصر المنفصل + صلة الميم \n 3. توسط المنفصل + إسكان الميم \n 4. توسط المنفصل + صلة الميم",
  "qalun-unit-3-u3-l1": "## الهمزتان من كلمة (مع الإدخال)\n\n إذا التقت همزتا قطع في كلمة واحدة، فإن قالون يقرأ **بتسهيل الهمزة الثانية** مع **إدخال ألف الفصل** بينهما (بمقدار حركتين).\n\n أَأَ \n\n#### المفتوحتان (أَأَنذَرْتَهُمْ)\n\nبتحقيق الأولى وتسهيل الثانية بين الهمزة والألف، مع الإدخال (ءَاـأَنذَرْتَهُمْ).\n\n أَإِ \n\n#### المفتوحة فمكسورة (أَءِنَّكُمْ)\n\nبتحقيق الأولى وتسهيل الثانية بين الهمزة والياء، مع الإدخال (ءَاـإِنَّكُمْ).\n\n أَأُ \n\n#### المفتوحة فمضمومة (أَؤُنَبِّئُكُم)\n\nبتحقيق الأولى وتسهيل الثانية بين الهمزة والواو، مع الإدخال (ءَاـؤُنَبِّئُكُم).\n\n **استثناء:** كلمة (أَئِمَّةً) يقرؤها بتسهيل الثانية دون إدخال.",
  "qalun-unit-3-u3-l2": "## الهمزتان من كلمتين\n\n همزتا القطع المتلاصقتان وصلاً في كلمتين. لهما حالتان: متفقتان في الحركة، ومختلفتان.\n\n### أولاً: المتفقتان في الحركة\n\n* \n **1. المفتوحتان (جَاءَ أَمْرُنَا):** يُسقط الهمزة الأولى بالكلية ويحقق الثانية. (مع جواز القصر والتوسط في المد قبلها).\n\n* \n **2. المكسورتان (هَؤُلاَءِ إِن كُنتُمْ):** يُسهّل الهمزة الأولى بينها وبين الياء، ويحقق الثانية.\n\n* \n **3. المضمومتان (أَوْلِيَاءُ أُوْلَئِكَ):** يُسهّل الهمزة الأولى بينها وبين الواو، ويحقق الثانية.\n\n### ثانياً: المختلفتان في الحركة\n\nالقاعدة فيها: تُسَهَّل الهمزة الثانية وفق حركة الأولى:\n\n **مفتوحة فمكسورة:** تُسهل الثانية بين الهمزة والياء (شُهَدَاءَ إِذْ).\n\n **مفتوحة فمضمومة:** تُسهل الثانية بين الهمزة والواو (جَاءَ أُمَّةً).\n\n **مكسورة فمفتوحة:** تُبدل الثانية ياءً خالصة (مِّنَ السَّمَاءِ آيَةً).\n\n **مضمومة فمفتوحة:** تُبدل الثانية واواً خالصة (يَشَاءُ إِلَى).\n\n **مضمومة فمكسورة (يَشَاءُ إِلَىٰ):** فيها وجهان، التسهيل أو الإبدال واواً مكسورة.",
  "qalun-unit-4-u4-l1": "## الإدغام في كلمات مخصوصة\n\n الأصل عند قالون هو الإظهار كحفص في كثير من المواضع التي يدغمها غيره، لكن له إدغامات في كلمات مخصوصة، ومن أبرزها:\n\n* \n **1. (يَلْهَث ذَّلِكَ) في الأعراف:**\n\nلقالون فيها الوجهان: **الإدغام** (يَلْهَذَّلِكَ)، و**الإظهار** (يَلْهَثْ ذَّلِكَ).\n\n* \n **2. (ارْكَب مَّعَنَا) في هود:**\n\nلقالون فيها الوجهان أيضاً: **الإدغام** (ارْكَمَّعَنَا)، و**الإظهار** (ارْكَبْ مَّعَنَا).\n\n* \n **3. (يُعَذِّبُ مَن يَشَاءُ) في البقرة:**\n\nيقرؤها بالإدغام (يُعَذِّمَّن) لأن الباء عنده ساكنة في هذا الموضع.",
  "qalun-unit-4-u4-l2": "## أحكام النون الساكنة والتنوين\n\n قواعد النون الساكنة والتنوين عند قالون مطابقة لما عند حفص من حيث (الإظهار، الإدغام، القلب، الإخفاء).\n\n### استثناءات هامة:\n\n* \n **يس والقرآن، ن والقلم:**\n\nيقرأ قالون بـ **الإظهار** (يسنْ وَالْقُرْآنِ)، (نُوْنْ وَالْقَلَمِ) حال الوصل.",
  "qalun-unit-5-u5-l1": "## ياءات الإضافة\n\n ياء الإضافة هي الياء الزائدة الدالة على المتكلم. مذهب قالون فيها يعتمد على الحرف الذي يقع بعدها:\n\n#### 1. بعدها همزة قطع مفتوحة:\n\nالفتح (إِنِّيَ أَعْلَمُ).\n\n#### 2. بعدها همزة قطع مكسورة:\n\nالفتح (مِن دُونِيَ آلِهَةً) إلا في كلمات مخصوصة.\n\n#### 3. بعدها همزة وصل:\n\nالفتح، سواء كانت همزة وصل مفردة أو مع لام التعريف (إِنِّيَ اصْطَفَيْتُكَ).\n\n#### 4. بعدها أي حرف آخر:\n\nالإسكان كالأصل، إلا في كلمات مثل (وَمَحْيَايَ) يقرؤها بالسكون.",
  "qalun-unit-5-u5-l2": "## الياءات الزوائد\n\n الياء الزائدة هي ياء متطرفة تُحذف في رسم المصحف العثماني تخفيفاً. يثبت قالون بعض هذه الياءات وصلاً.\n\n### أمثلة على ما يثبته قالون وصلاً فقط:\n\n* \n **(يَوْمَ يَأْتِ) في هود:**\n\nيقرؤها بإثبات الياء وصلاً (يَوْمَ يَأْتِي لا تَكَلَّمُ)، ويحذفها وقفاً.\n\n* \n **(دَعْوَةَ الدَّاعِ إِذَا دَعَانِ) في البقرة:**\n\nيثبت ياء (الدَّاعِي) و (دَعَانِي) في الوصل، ويحذفهما في الوقف."
};

export function getDefaultLessonText(rawiId: string, unitId: string, lessonId: string): string {
  const globalKey = `${rawiId}-${unitId}-${lessonId}`;
  if (defaultLessonTexts[globalKey]) {
    return defaultLessonTexts[globalKey];
  }
  if (defaultLessonTexts[lessonId]) {
    return defaultLessonTexts[lessonId];
  }
  return "## محتوى الدرس\n\nاكتب المادة العلمية وقواعد هذا الدرس هنا...";
}
